    #[test]
    fn nullable_batches_install_typed_casts_in_declaration_order() {
        #[derive(Clone, PartialEq, Debug)]
        struct Count(u32);

        let target = ValueType::of::<Option<Count>>();
        ValueTypes::register_cast::<Count, Option<Count>>(|_| None);
        ValueTypes::register_nullable_types(&const { [
            NullableRegistration::of::<String>(),
            NullableRegistration::of::<Count>(),
            NullableRegistration::of::<Option<Count>>(),
        ] });
        assert!(ValueTypes::nullable_inner(target).unwrap().is::<Count>());
        let source: BoxedValue = Rc::new(Count(7));
        let wrapped = ValueTypes::try_cast(&source, target).unwrap();
        assert_eq!(wrapped.downcast_ref::<Option<Count>>(), Some(&Some(Count(7))));
        let nested = ValueTypes::try_cast(&wrapped, ValueType::of::<Option<Option<Count>>>()).unwrap();
        assert_eq!(nested.downcast_ref::<Option<Option<Count>>>(), Some(&Some(Some(Count(7)))));
        assert_eq!(ValueTypes::null_value(target).unwrap().downcast_ref::<Option<Count>>(), Some(&None));
    }

    #[test]
    fn registering_a_reference_twice_preserves_a_custom_handle_cast() {
        #[derive(PartialEq)]
        struct Model;

        ValueTypes::register_reference::<Model>();
        let model = Rc::new(Model);
        let boxed = model.clone() as BoxedValue;
        let target = ValueType::of::<Rc<Model>>();
        let handle = ValueTypes::try_cast(&boxed, target).unwrap();
        assert!(Rc::ptr_eq(&model, handle.downcast_ref::<Rc<Model>>().unwrap()));
        let replacement = Rc::new(Model);
        let other = replacement.clone();
        ValueTypes::register_boxed_cast::<Model, Rc<Model>>(move |_| Some(other.clone()));
        ValueTypes::register_reference::<Model>();
        let handle = ValueTypes::try_cast(&boxed, target).unwrap();
        assert!(Rc::ptr_eq(&replacement, handle.downcast_ref::<Rc<Model>>().unwrap()));
    }

    #[test]
    fn replacing_one_conversion_route_preserves_the_other_registered_views() {
        #[derive(Clone, PartialEq)]
        struct Source(i32);
        #[derive(Clone, Debug, PartialEq)]
        struct Target(i32);

        let source: BoxedValue = Rc::new(Source(10));
        let target = ValueType::of::<Target>();
        let check = |expected: [i32; 3]| {
            let registered = ValueTypes::try_convert_registered(&source, target).unwrap();
            let cast = ValueTypes::try_cast(&source, target).unwrap();
            let property = ValueTypes::try_convert_for_property(source.as_any(), target.id()).unwrap();
            for (value, expected) in [registered, cast, property].iter().zip(expected) {
                assert_eq!(value.downcast_ref::<Target>(), Some(&Target(expected)));
            }
        };
        ValueTypes::register_cast::<Source, Target>(|v| Target(v.0 + 1));
        check([11, 11, 11]);
        ValueTypes::register_conversion::<Source, Target>(|v| Some(Target(v.0 + 2)));
        check([12, 11, 11]);
        ValueTypes::register_boxed_cast::<Source, Target>(|v| Some(Target(v.downcast_ref::<Source>()?.0 + 3)));
        check([13, 13, 11]);
        ValueTypes::register_boxed_conversion::<Source, Target>(|v| Some(Target(v.downcast_ref::<Source>()?.0 + 4)));
        check([14, 13, 11]);

        // The borrowed operation owns a snapshot while the callback installs its successor.
        let increment = 5;
        ValueTypes::register_cast::<Source, Target>(move |v| {
            ValueTypes::register_cast::<Source, Target>(|v| Target(v.0 + 6));
            Target(v.0 + increment)
        });
        let first = ValueTypes::try_convert_for_property(source.as_any(), target.id()).unwrap();
        assert_eq!(first.downcast_ref::<Target>(), Some(&Target(15)));
        check([16, 16, 16]);
    }

    #[test]
    fn registered_numeric_conversions_keep_exact_target_types_and_checked_edges() {
        let input: BoxedValue = Rc::new(f64::from_bits(0x7ff8_1234_5678_9012));
        let float = ValueTypes::try_convert_registered(&input, ValueType::of::<Option<f64>>()).unwrap();
        assert_eq!(float.downcast_ref::<Option<f64>>().unwrap().unwrap().to_bits(), 0x7ff8_1234_5678_9012);
        assert!(ValueTypes::try_convert_registered(&input, ValueType::of::<i64>()).is_none());

        for (value, expected) in [(-1.5, -2), (-0.5, 0), (2.5, 2), (3.5, 4)] {
            let input: BoxedValue = Rc::new(value as f64);
            let int = ValueTypes::try_convert_registered(&input, ValueType::of::<Option<i32>>()).unwrap();
            assert_eq!(int.downcast_ref::<Option<i32>>(), Some(&Some(expected)));
        }
        let large: BoxedValue = Rc::new(u64::MAX);
        assert!(ValueTypes::try_convert_registered(&large, ValueType::of::<i64>()).is_none());
        let unsigned = ValueTypes::try_convert_registered(&large, ValueType::of::<u64>()).unwrap();
        assert_eq!(unsigned.downcast_ref::<u64>(), Some(&u64::MAX));
    }

    trait IShape {
        fn sides(&self) -> i32;
    }

    impl PartialEq for dyn IShape {
        fn eq(&self, other: &Self) -> bool {
            std::ptr::addr_eq(self as *const Self, other as *const Self)
        }
    }

    struct ShapeBase {
        sides: i32,
    }

    impl PartialEq for ShapeBase {
        fn eq(&self, other: &Self) -> bool {
            std::ptr::eq(self, other)
        }
    }

    impl IShape for ShapeBase {
        fn sides(&self) -> i32 {
            self.sides
        }
    }

    struct Square {
        base: Rc<ShapeBase>,
    }

    impl PartialEq for Square {
        fn eq(&self, other: &Self) -> bool {
            std::ptr::eq(self, other)
        }
    }

    struct Circle {
        base: Rc<ShapeBase>,
    }

    impl PartialEq for Circle {
        fn eq(&self, other: &Self) -> bool {
            std::ptr::eq(self, other)
        }
    }

    struct Unrelated;

    impl PartialEq for Unrelated {
        fn eq(&self, other: &Self) -> bool {
            std::ptr::eq(self, other)
        }
    }

    fn register_shapes() {
        ValueTypes::register_reference::<ShapeBase>();
        ValueTypes::register_reference::<Square>();
        ValueTypes::register_reference::<Circle>();
        ValueTypes::register_reference::<Unrelated>();
        ValueTypes::register_nullable::<Rc<dyn IShape>>();
        // Registered for the object form, with the box.
        ValueTypes::register_boxed_cast::<Square, Rc<ShapeBase>>(|object| {
            let any: Rc<dyn std::any::Any> = object.clone();
            any.downcast::<Square>().ok().map(|square| square.base.clone())
        });
        ValueTypes::register_cast::<Square, Rc<dyn IShape>>(|square| square.base.clone() as Rc<dyn IShape>);
        // Registered for the handle form.
        ValueTypes::register_cast::<Rc<Circle>, Rc<ShapeBase>>(|circle| circle.base.clone());
        ValueTypes::register_cast::<Rc<Circle>, Rc<dyn IShape>>(|circle| circle.base.clone() as Rc<dyn IShape>);
    }

    fn sides_of(value: &BoxedValue) -> i32 {
        if let Some(base) = value.downcast_ref::<ShapeBase>() {
            return base.sides;
        }
        if let Some(base) = value.downcast_ref::<Rc<ShapeBase>>() {
            return base.sides;
        }
        if let Some(Some(base)) = value.downcast_ref::<Option<Rc<ShapeBase>>>() {
            return base.sides;
        }
        if let Some(shape) = value.downcast_ref::<Rc<dyn IShape>>() {
            return shape.sides();
        }
        if let Some(Some(shape)) = value.downcast_ref::<Option<Rc<dyn IShape>>>() {
            return shape.sides();
        }
        panic!("unexpected type {}", (**value).type_name());
    }

