    // Not upstream tests: the conversions between numbers and text with a culture
    // (`TypeUtilities.TryConvert(to, value, culture)`).
    fn comma_culture() -> CultureInfo {
        let numbers = crate::utilities::NumberFormatInfo::new()
            .with_number_decimal_separator(",")
            .with_number_group_separator(".");
        CultureInfo::get_culture_info("de-DE").with_number_format(numbers)
    }

    #[test]
    fn a_number_becomes_text_as_the_culture_formats_it() {
        let culture = comma_culture();
        let value: BoxedValue = Rc::new(1.5f64);

        let text = ValueTypes::try_convert_with_culture(Some(&value), ValueType::of::<String>(), &culture);
        assert_eq!(text.flatten().and_then(|text| text.downcast_ref::<String>().cloned()).as_deref(), Some("1,5"));

        let nullable: BoxedValue = Rc::new(Some(2.25f64));
        let text = ValueTypes::try_convert_with_culture(Some(&nullable), ValueType::of::<Option<String>>(), &culture);
        let text = text.flatten().and_then(|text| text.downcast_ref::<Option<String>>().cloned()).flatten();
        assert_eq!(text.as_deref(), Some("2,25"));

        // The invariant culture is the conversion without a culture.
        let invariant = CultureInfo::invariant_culture();
        let text = ValueTypes::try_convert_with_culture(Some(&value), ValueType::of::<String>(), &invariant);
        assert_eq!(text.flatten().and_then(|text| text.downcast_ref::<String>().cloned()).as_deref(), Some("1.5"));
    }

    #[test]
    fn text_becomes_a_number_as_the_culture_writes_it() {
        let culture = comma_culture();
        let convert = |text: &str, target: ValueType| {
            let text: BoxedValue = Rc::new(text.to_string());
            ValueTypes::try_convert_with_culture(Some(&text), target, &culture).flatten()
        };

        let number = convert("1.234,5", ValueType::of::<f64>()).expect("a number");
        assert_eq!(number.downcast_ref::<f64>(), Some(&1234.5));
        let number = convert(" 2,5 ", ValueType::of::<Option<f64>>()).expect("a nullable number");
        assert_eq!(number.downcast_ref::<Option<f64>>(), Some(&Some(2.5)));
        // An integer has no separators.
        let number = convert("12", ValueType::of::<i32>()).expect("an integer");
        assert_eq!(number.downcast_ref::<i32>(), Some(&12));
        assert!(convert("1,5", ValueType::of::<i32>()).is_none());
        assert!(convert("x", ValueType::of::<f64>()).is_none());

        // Values that are not numbers or text convert as without a culture.
        let flag: BoxedValue = Rc::new(true);
        let text = ValueTypes::try_convert_with_culture(Some(&flag), ValueType::of::<String>(), &culture);
        assert_eq!(text.flatten().and_then(|text| text.downcast_ref::<String>().cloned()).as_deref(), Some("True"));
    }

    // Not upstream tests (upstream has none for the table of `TypeUtilities`): the
    // conversions between the numeric types, `TypeUtilities.Conversions` with
    // `Convert.ChangeType`.
    fn convert_number<TFrom: PartialEq + 'static, TTo: Clone + 'static>(value: TFrom) -> Option<TTo> {
        let value: BoxedValue = Rc::new(value);
        let converted = ValueTypes::try_convert(Some(&value), ValueType::of::<TTo>()).flatten()?;
        Some(converted.downcast_ref::<TTo>().expect("a value of the target type").clone())
    }

    #[track_caller]
    fn assert_number_converts<TFrom, TTo>(value: TFrom, expected: TTo)
    where
        TFrom: Clone + PartialEq + fmt::Debug + 'static,
        TTo: Clone + PartialEq + fmt::Debug + 'static,
    {
        // To the type and to its nullable form, from the type and from its nullable form.
        assert_eq!(convert_number::<TFrom, TTo>(value.clone()), Some(expected.clone()), "from {value:?}");
        assert_eq!(convert_number::<TFrom, Option<TTo>>(value.clone()), Some(Some(expected.clone())), "from {value:?}");
        assert_eq!(convert_number::<Option<TFrom>, TTo>(Some(value.clone())), Some(expected.clone()), "from {value:?}");
        assert_eq!(
            convert_number::<Option<TFrom>, Option<TTo>>(Some(value.clone())),
            Some(Some(expected)),
            "from {value:?}"
        );
    }

    #[test]
    fn every_number_converts_to_every_numeric_type() {
        use crate::utilities::Decimal;

        macro_rules! pairs {
            (@from $from:expr => [$($to:expr),*]) => {
                $( assert_number_converts($from, $to); )*
            };
            ($($from:expr),* => $all:tt) => {
                $( pairs!(@from $from => $all); )*
            };
        }
        pairs!(
            1i8, 1i16, 1i32, 1i64, 1u8, 1u16, 1u32, 1u64, 1isize, 1usize, 1f32, 1f64, Decimal::ONE
            => [1i8, 1i16, 1i32, 1i64, 1u8, 1u16, 1u32, 1u64, 1isize, 1usize, 1f32, 1f64, Decimal::ONE]
        );
    }

    #[test]
    fn floating_point_numbers_and_decimals_convert_to_each_other() {
        use crate::utilities::Decimal;

        let decimal = |text: &str| Decimal::parse(text).expect("a decimal");

        assert_number_converts(2.5f64, decimal("2.5"));
        assert_number_converts(-0.1f64, decimal("-0.1"));
        assert_number_converts(2.5f32, decimal("2.5"));
        // A float has seven digits, a double fifteen.
        assert_number_converts(0.1f32, decimal("0.1"));
        assert_number_converts(1.0f64 / 3.0, decimal("0.333333333333333"));
        assert_number_converts(decimal("2.5"), 2.5f64);
        assert_number_converts(decimal("2.50"), 2.5f32);
        assert_number_converts(decimal("-0.1"), -0.1f64);

        // `Convert.ToDecimal` fails outside the range of the type: no conversion.
        for value in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY, 1e30, -1e30] {
            assert_eq!(convert_number::<f64, Decimal>(value), None, "{value}");
            assert_eq!(convert_number::<f64, Option<Decimal>>(value), None, "{value}");
        }
        for value in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY, 1e30] {
            assert_eq!(convert_number::<f32, Decimal>(value), None, "{value}");
            assert_eq!(convert_number::<f32, Option<Decimal>>(value), None, "{value}");
        }

        // A null converts to the nullable form alone.
        assert_eq!(convert_number::<Option<f64>, Option<Decimal>>(None), Some(None));
        assert_eq!(convert_number::<Option<f64>, Decimal>(None), None);
        assert_eq!(convert_number::<Option<Decimal>, Option<f64>>(None), Some(None));
        assert_eq!(convert_number::<Option<Decimal>, f64>(None), None);
    }

    #[test]
    fn a_decimal_converts_to_an_integer_rounded_and_in_range() {
        use crate::utilities::Decimal;

        let decimal = |text: &str| Decimal::parse(text).expect("a decimal");

        // Midpoints go to the even integer (`Convert.ToInt32(decimal)`).
        assert_number_converts(decimal("2.5"), 2i32);
        assert_number_converts(decimal("3.5"), 4i32);
        assert_number_converts(decimal("-2.5"), -2i64);
        assert_number_converts(decimal("2.6"), 3u8);
        assert_number_converts(decimal("255.4"), 255u8);
        assert_number_converts(decimal("-0.5"), 0u32);
        assert_number_converts(Decimal::from(u64::MAX), u64::MAX);
        assert_number_converts(Decimal::from(i64::MIN), i64::MIN);

        // Out of the range of the target: no conversion.
        assert_eq!(convert_number::<Decimal, u8>(decimal("255.5")), None);
        assert_eq!(convert_number::<Decimal, Option<u8>>(decimal("256")), None);
        assert_eq!(convert_number::<Decimal, u32>(decimal("-1")), None);
        assert_eq!(convert_number::<Decimal, i8>(decimal("-129")), None);
        assert_eq!(convert_number::<Decimal, i64>(Decimal::MAX_VALUE), None);
        assert_eq!(convert_number::<Decimal, u64>(Decimal::MIN_VALUE), None);

        // The integers convert exactly.
        assert_number_converts(i64::MIN, Decimal::from(i64::MIN));
        assert_number_converts(u64::MAX, Decimal::from(u64::MAX));
    }

    #[test]
    fn numbers_convert_between_the_other_types_as_the_runtime_converts_them() {
        // A floating point number becomes an integer rounded to even, in range.
        assert_number_converts(2.5f64, 2i32);
        assert_number_converts(3.5f32, 4i32);
        assert_eq!(convert_number::<f64, i32>(f64::NAN), None);
        assert_eq!(convert_number::<f64, u8>(256.0), None);
        assert_eq!(convert_number::<f64, u8>(-1.0), None);
        // An integer becomes an integer in range.
        assert_number_converts(255i32, 255u8);
        assert_eq!(convert_number::<i32, u8>(256), None);
        assert_eq!(convert_number::<i32, Option<u8>>(-1), None);
        assert_eq!(convert_number::<u64, i64>(u64::MAX), None);
        // A double narrows to a float without a range check.
        assert_eq!(convert_number::<f64, f32>(1e300), Some(f32::INFINITY));
    }

    #[test]
    fn booleans_and_numbers_convert_to_each_other() {
        use crate::utilities::Decimal;

        // `Convert.ToInt32(bool)` and its siblings: true is one, false is zero.
        macro_rules! from_boolean {
            ($($one:expr, $zero:expr);* $(;)?) => {
                $(
                    assert_number_converts(true, $one);
                    assert_number_converts(false, $zero);
                )*
            };
        }
        from_boolean!(
            1i8, 0i8; 1u8, 0u8; 1i16, 0i16; 1u16, 0u16; 1i32, 0i32; 1u32, 0u32; 1i64, 0i64; 1u64, 0u64;
            1f32, 0f32; 1f64, 0f64; Decimal::ONE, Decimal::ZERO;
        );

        // `Convert.ToBoolean(number)`: true unless the number is zero.
        macro_rules! to_boolean {
            ($($value:expr => $expected:expr),* $(,)?) => {
                $( assert_number_converts($value, $expected); )*
            };
        }
        to_boolean!(
            0i8 => false, -1i8 => true, 0u8 => false, 2u8 => true, 0i16 => false, -3i16 => true,
            0u16 => false, 4u16 => true, 0i32 => false, i32::MIN => true, 0u32 => false, 5u32 => true,
            0i64 => false, i64::MAX => true, 0u64 => false, u64::MAX => true,
            0f32 => false, 0.5f32 => true, 0f64 => false, -0f64 => false, -0.25f64 => true,
            Decimal::ZERO => false, Decimal::from(-7) => true,
        );
        // Not-a-number and the infinities are not zero.
        assert_eq!(convert_number::<f64, bool>(f64::NAN), Some(true));
        assert_eq!(convert_number::<f64, Option<bool>>(f64::INFINITY), Some(Some(true)));
        assert_eq!(convert_number::<f32, bool>(f32::NAN), Some(true));

        // No cell of the table joins the boolean and the character.
        assert_eq!(convert_number::<bool, char>(true), None);
        assert_eq!(convert_number::<bool, Option<char>>(true), None);
        assert_eq!(convert_number::<char, bool>('1'), None);
        assert_eq!(convert_number::<char, Option<bool>>('1'), None);
        // The text of a boolean, in both directions, is as before.
        assert_eq!(convert_number::<bool, String>(true), Some("True".to_string()));
        assert_eq!(convert_number::<String, bool>("false".to_string()), Some(false));
    }

    #[test]
    fn characters_and_integers_convert_to_each_other() {
        use crate::utilities::Decimal;

        // In both directions for every integer type of the table.
        macro_rules! codes {
            ($($code:expr),*) => {
                $(
                    assert_number_converts('A', $code);
                    assert_number_converts($code, 'A');
                )*
            };
        }
        codes!(65i8, 65u8, 65i16, 65u16, 65i32, 65u32, 65i64, 65u64);

        // `Convert.ToSByte(char)` and its siblings fail outside the range of the integer.
        assert_eq!(convert_number::<char, i8>('\u{e9}'), None);
        assert_number_converts('\u{e9}', 0xE9u8);
        assert_eq!(convert_number::<char, u8>('\u{100}'), None);
        assert_eq!(convert_number::<char, Option<u8>>('\u{100}'), None);
        assert_eq!(convert_number::<char, i16>('\u{8000}'), None);
        assert_number_converts('\u{8000}', 0x8000u16);
        assert_number_converts('\u{ffff}', 0xFFFFi32);
        assert_number_converts('\u{ffff}', 0xFFFFu64);

        // `Convert.ToChar(integer)` fails outside the range of the 16-bit characters.
        assert_eq!(convert_number::<i8, char>(-1), None);
        assert_eq!(convert_number::<i16, char>(-1), None);
        assert_eq!(convert_number::<i32, char>(-1), None);
        assert_eq!(convert_number::<i32, char>(0x1_0000), None);
        assert_eq!(convert_number::<u32, Option<char>>(0x1_0000), None);
        assert_eq!(convert_number::<i64, char>(i64::MAX), None);
        assert_eq!(convert_number::<u64, char>(u64::MAX), None);
        assert_number_converts(0xFFFFu16, '\u{ffff}');
        assert_number_converts(0u8, '\0');
        // A code of the surrogate range is no character here.
        assert_eq!(convert_number::<u16, char>(0xD800), None);
        // A character of more than 16 bits, which the managed original does not have, has
        // no 16-bit code.
        assert_eq!(convert_number::<char, u16>('\u{1F600}'), None);
        assert_number_converts('\u{1F600}', 0x1F600u32);

        // No cell of the table joins the character and the floating point numbers or
        // the decimal.
        assert_eq!(convert_number::<char, f32>('A'), None);
        assert_eq!(convert_number::<char, f64>('A'), None);
        assert_eq!(convert_number::<char, Option<f64>>('A'), None);
        assert_eq!(convert_number::<char, Decimal>('A'), None);
        assert_eq!(convert_number::<f32, char>(65.0), None);
        assert_eq!(convert_number::<f64, char>(65.0), None);
        assert_eq!(convert_number::<Decimal, char>(Decimal::from(65)), None);
        // The text of a character, in both directions, is as before.
        assert_eq!(convert_number::<char, String>('A'), Some("A".to_string()));
        assert_eq!(convert_number::<String, char>("A".to_string()), Some('A'));
    }

    #[test]
    fn numbers_and_text_convert_to_each_other() {
        use crate::utilities::Decimal;

        let decimal = |text: &str| Decimal::parse(text).expect("a decimal");

        assert_number_converts(decimal("1.50"), "1.50".to_string());
        assert_number_converts(2.5f64, "2.5".to_string());
        assert_number_converts(7i32, "7".to_string());
        assert_number_converts("1.50".to_string(), decimal("1.50"));
        assert_number_converts("2.5".to_string(), 2.5f64);
        assert_number_converts("7".to_string(), 7i32);
        assert_eq!(convert_number::<String, Decimal>("x".to_string()), None);
        assert_eq!(convert_number::<String, Option<Decimal>>("x".to_string()), None);

        // With a culture: its decimal separator.
        let culture = comma_culture();
        let value: BoxedValue = Rc::new(decimal("1.5"));
        let text = ValueTypes::try_convert_with_culture(Some(&value), ValueType::of::<String>(), &culture);
        assert_eq!(text.flatten().and_then(|text| text.downcast_ref::<String>().cloned()).as_deref(), Some("1,5"));
        let text: BoxedValue = Rc::new("2,5".to_string());
        let number = ValueTypes::try_convert_with_culture(Some(&text), ValueType::of::<Option<Decimal>>(), &culture);
        assert_eq!(number.flatten().and_then(|n| n.downcast_ref::<Option<Decimal>>().cloned()), Some(Some(decimal("2.5"))));
        // The other conversions of numbers do not depend on the culture.
        let value: BoxedValue = Rc::new(2.5f64);
        let number = ValueTypes::try_convert_with_culture(Some(&value), ValueType::of::<Option<Decimal>>(), &culture);
        assert_eq!(number.flatten().and_then(|n| n.downcast_ref::<Option<Decimal>>().cloned()), Some(Some(decimal("2.5"))));
    }

    #[test]
    fn the_implicit_conversions_of_numbers_are_those_of_the_language() {
        use crate::utilities::Decimal;

        let implicit = |value: &dyn std::any::Any, target: TypeId| ValueTypes::try_convert_implicit(value, target);
        let decimal_of = |value: &dyn std::any::Any| {
            implicit(value, TypeId::of::<Decimal>()).map(|v| *v.downcast_ref::<Decimal>().expect("a decimal"))
        };

        // Every integer converts to the decimal.
        assert_eq!(decimal_of(&7i8), Some(Decimal::from(7)));
        assert_eq!(decimal_of(&7u8), Some(Decimal::from(7)));
        assert_eq!(decimal_of(&7i16), Some(Decimal::from(7)));
        assert_eq!(decimal_of(&7u16), Some(Decimal::from(7)));
        assert_eq!(decimal_of(&7i32), Some(Decimal::from(7)));
        assert_eq!(decimal_of(&7u32), Some(Decimal::from(7)));
        assert_eq!(decimal_of(&i64::MIN), Some(Decimal::from(i64::MIN)));
        assert_eq!(decimal_of(&u64::MAX), Some(Decimal::from(u64::MAX)));
        // A floating point number does not, nor the decimal to anything else.
        assert_eq!(decimal_of(&2.5f64), None);
        assert_eq!(decimal_of(&2.5f32), None);
        assert!(implicit(&Decimal::ONE, TypeId::of::<f64>()).is_none());
        assert!(implicit(&Decimal::ONE, TypeId::of::<i32>()).is_none());
        // The implicit conversion gives the type itself, not its nullable form.
        assert!(implicit(&7i32, TypeId::of::<Option<Decimal>>()).is_none());

        // The widening conversions, and no narrowing one.
        assert!(implicit(&7i32, TypeId::of::<f64>()).is_some_and(|v| v.downcast_ref::<f64>() == Some(&7.0)));
        assert!(implicit(&7i32, TypeId::of::<i64>()).is_some_and(|v| v.downcast_ref::<i64>() == Some(&7)));
        assert!(implicit(&7.5f32, TypeId::of::<f64>()).is_some_and(|v| v.downcast_ref::<f64>() == Some(&7.5)));
        assert!(implicit(&7i64, TypeId::of::<i32>()).is_none());
        assert!(implicit(&7.0f64, TypeId::of::<f32>()).is_none());
        assert!(implicit(&7i32, TypeId::of::<u32>()).is_none());
        assert!(implicit(&7.0f64, TypeId::of::<i32>()).is_none());
    }

    #[test]
    fn the_implicit_conversions_of_a_character_and_of_a_boolean_are_those_of_the_table() {
        use crate::utilities::Decimal;

        let implicit = |value: &dyn std::any::Any, target: TypeId| ValueTypes::try_convert_implicit(value, target);

        // A character converts to the integer types of its row.
        assert!(implicit(&'A', TypeId::of::<u16>()).is_some_and(|v| v.downcast_ref::<u16>() == Some(&65)));
        assert!(implicit(&'A', TypeId::of::<i32>()).is_some_and(|v| v.downcast_ref::<i32>() == Some(&65)));
        assert!(implicit(&'A', TypeId::of::<u32>()).is_some_and(|v| v.downcast_ref::<u32>() == Some(&65)));
        assert!(implicit(&'A', TypeId::of::<i64>()).is_some_and(|v| v.downcast_ref::<i64>() == Some(&65)));
        // The row leaves the other integers out.
        assert!(implicit(&'A', TypeId::of::<i8>()).is_none());
        assert!(implicit(&'A', TypeId::of::<u8>()).is_none());
        assert!(implicit(&'A', TypeId::of::<i16>()).is_none());
        assert!(implicit(&'A', TypeId::of::<u64>()).is_none());
        // It names the floating point numbers and the decimal, for which the conversion
        // of the runtime fails.
        assert!(implicit(&'A', TypeId::of::<f32>()).is_none());
        assert!(implicit(&'A', TypeId::of::<f64>()).is_none());
        assert!(implicit(&'A', TypeId::of::<Decimal>()).is_none());
        assert!(implicit(&'A', TypeId::of::<bool>()).is_none());
        // Nothing converts to a character implicitly.
        assert!(implicit(&65u16, TypeId::of::<char>()).is_none());
        assert!(implicit(&65i32, TypeId::of::<char>()).is_none());

        // The row of the boolean names the boolean alone, and no row names it.
        assert!(implicit(&true, TypeId::of::<i32>()).is_none());
        assert!(implicit(&true, TypeId::of::<f64>()).is_none());
        assert!(implicit(&true, TypeId::of::<Decimal>()).is_none());
        assert!(implicit(&1i32, TypeId::of::<bool>()).is_none());
        assert!(implicit(&1.0f64, TypeId::of::<bool>()).is_none());
    }

    /// `ValueTypes::compare`: the order of two `IComparable` operands of the managed original,
    /// the right one converted to the type of the left one (`Convert.ChangeType`).
    #[test]
    fn values_are_ordered_with_the_right_operand_converted_to_the_type_of_the_left_one() {
        use std::cmp::Ordering::{Equal, Greater, Less};

        fn b<T: PartialEq + 'static>(value: T) -> BoxedValue {
            Rc::new(value)
        }
        let compare = |a: BoxedValue, b: BoxedValue| ValueTypes::compare(&a, &b);

        // Numbers of the same type and across types.
        assert_eq!(compare(b(1i32), b(2i32)), Some(Less));
        assert_eq!(compare(b(2u8), b(2i64)), Some(Equal));
        assert_eq!(compare(b(3i32), b(2.5f64)), Some(Greater));
        assert_eq!(compare(b(5.4f64), b(5i32)), Some(Greater));
        // The right operand becomes an integer of the left type, midpoints to even.
        assert_eq!(compare(b(5i32), b(5.4f64)), Some(Equal));
        assert_eq!(compare(b(2i32), b(2.5f64)), Some(Equal));
        assert_eq!(compare(b(3i32), b(2.5f64)), Some(Greater));
        // Out of the range of the left type: both as floating point numbers.
        assert_eq!(compare(b(1i32), b(1e20f64)), Some(Less));
        assert_eq!(compare(b(1u8), b(-1i32)), Some(Greater));
        // Not-a-number is less than every number and equal to itself.
        assert_eq!(compare(b(f64::NAN), b(1.0f64)), Some(Less));
        assert_eq!(compare(b(f64::NAN), b(f64::NAN)), Some(Equal));
        assert_eq!(compare(b(1.0f32), b(f64::NAN)), Some(Greater));
        assert_eq!(compare(b(5i32), b(f64::NAN)), Some(Greater));
        assert_eq!(compare(b(crate::utilities::Decimal::ONE), b(2i32)), Some(Less));

        // Text, ordinally; text converts to the number on the left and the reverse.
        assert_eq!(compare(b("a".to_string()), b("b".to_string())), Some(Less));
        assert_eq!(compare(b("B".to_string()), b("a".to_string())), Some(Less));
        assert_eq!(compare(b("a"), b("a".to_string())), Some(Equal));
        assert_eq!(compare(b(42i32), b("41".to_string())), Some(Greater));
        assert_eq!(compare(b("5".to_string()), b(5i32)), Some(Equal));
        assert_eq!(compare(b(42i32), b("not-an-integer".to_string())), None);
        assert_eq!(compare(b(42i32), b("999999999999999999999999999999".to_string())), None);

        // Booleans and characters, with the numbers they convert to and from.
        assert_eq!(compare(b(false), b(true)), Some(Less));
        assert_eq!(compare(b(true), b(1.5f64)), Some(Equal));
        assert_eq!(compare(b(1i32), b(true)), Some(Equal));
        assert_eq!(compare(b('a'), b('b')), Some(Less));
        assert_eq!(compare(b(65i32), b('A')), Some(Equal));
        assert_eq!(compare(b('A'), b(1.0f64)), None);

        // Nullable values by their contents; null and values without an order are not comparable.
        assert_eq!(compare(b(Some(3i32)), b(2i32)), Some(Greater));
        assert_eq!(compare(b(None::<i32>), b(1i32)), None);
        assert_eq!(compare(b(1i32), b(None::<BoxedValue>)), None);
        assert_eq!(compare(b(Unknown), b(Unknown)), None);
        assert_eq!(compare(b(1i32), b(Unknown)), None);
        assert!(ValueTypes::is_ordered(ValueType::of::<i32>()));
        assert!(!ValueTypes::is_ordered(ValueType::of::<Unknown>()));

        // An enumeration by its value, with values of the same enumeration only.
        register_named();
        assert_eq!(compare(b(NamedMode::First), b(NamedMode::Second)), Some(Less));
        assert_eq!(compare(b(NamedMode::Second), b(NamedMode::Second)), Some(Equal));
        assert_eq!(compare(b(NamedMode::First), b(0i32)), None);
        assert_eq!(compare(b(1i32), b(NamedMode::Second)), Some(Equal));
        assert!(ValueTypes::is_ordered(ValueType::of::<NamedMode>()));
    }

    /// A type registers its order; values that convert to it compare with it.
    #[test]
    fn registered_orderings_compare_values_of_the_type() {
        #[derive(Clone, Debug, PartialEq, PartialOrd)]
        struct Rank(i32);
        #[derive(Clone, Debug, PartialEq)]
        struct Reversed(i32);

        let rank = |value: i32| -> BoxedValue { Rc::new(Rank(value)) };
        assert_eq!(ValueTypes::compare(&rank(1), &rank(2)), None);

        ValueTypes::register_ordering::<Rank>();
        assert_eq!(ValueTypes::compare(&rank(1), &rank(2)), Some(std::cmp::Ordering::Less));
        assert_eq!(ValueTypes::compare(&rank(2), &rank(2)), Some(std::cmp::Ordering::Equal));
        // A number has an order but no conversion to the type: not comparable.
        assert_eq!(ValueTypes::compare(&rank(1), &(Rc::new(2i32) as BoxedValue)), None);
        ValueTypes::register_conversion::<i32, Rank>(|value| Some(Rank(*value)));
        assert_eq!(ValueTypes::compare(&rank(1), &(Rc::new(2i32) as BoxedValue)), Some(std::cmp::Ordering::Less));

        ValueTypes::register_ordering_by::<Reversed>(|a, b| Some(b.0.cmp(&a.0)));
        let reversed = |value: i32| -> BoxedValue { Rc::new(Reversed(value)) };
        assert_eq!(ValueTypes::compare(&reversed(1), &reversed(2)), Some(std::cmp::Ordering::Greater));
    }
}

