//! Runtime knowledge about value types for the untyped parts of the binding
//! system.
//!
//! An untyped value ([`BoxedValue`]) holds exactly one Rust type and offers
//! no way to ask "is this nullable", "can this be shown as text" or "can this
//! be converted to the target property's type". The managed runtime answers
//! those questions through reflection; here they are answered by a per-thread
//! table keyed by [`TypeId`], filled by explicit registration. Typed
//! (compiled) bindings whose source and target types match never consult the
//! table.

use crate::utilities::CultureInfo;
use crate::{AnyValue, BoxedValue, FerroObject, ObjectType, PropertyValue, Ref, StyledElement, TypeInfo, Upcast};
use std::any::TypeId;
use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::hash::{BuildHasherDefault, Hasher};
use std::rc::Rc;

/// Identifies the type of a value: the equivalent of a runtime type handle
/// for values that are not class instances.
#[derive(Clone, Copy)]
pub struct ValueType {
    id: TypeId,
    name: &'static str,
}

impl ValueType {
    /// The value type of `T`.
    #[inline]
    pub fn of<T: 'static>() -> Self {
        Self { id: TypeId::of::<T>(), name: std::any::type_name::<T>() }
    }

    /// Creates a value type from its parts.
    #[inline]
    pub fn new(id: TypeId, name: &'static str) -> Self {
        Self { id, name }
    }

    /// The value type of the contents of an untyped value.
    #[inline]
    pub fn of_value(value: &dyn AnyValue) -> Self {
        Self { id: value_type_id(&*value), name: value.type_name() }
    }

    /// The "any value" type: the type of targets that accept every value
    /// unconverted.
    #[inline]
    pub fn object() -> Self {
        Self::of::<Option<BoxedValue>>()
    }

    #[inline]
    pub fn id(&self) -> TypeId {
        self.id
    }

    #[inline]
    pub fn name(&self) -> &'static str {
        self.name
    }

    #[inline]
    pub fn is<T: 'static>(&self) -> bool {
        self.id == TypeId::of::<T>()
    }

    /// Whether this is the "any value" type (`Option<BoxedValue>` or
    /// `BoxedValue`).
    #[inline]
    pub fn is_object(&self) -> bool {
        self.is::<Option<BoxedValue>>() || self.is::<BoxedValue>()
    }

    /// Whether this is the string type.
    #[inline]
    pub fn is_string(&self) -> bool {
        self.is::<String>() || self.is::<Option<String>>()
    }
}

impl PartialEq for ValueType {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

impl Eq for ValueType {}

impl fmt::Debug for ValueType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name)
    }
}

impl fmt::Display for ValueType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name)
    }
}

/// The type ID of the contents of an untyped value.
#[inline]
pub(crate) fn value_type_id(value: &dyn AnyValue) -> TypeId {
    <dyn std::any::Any>::type_id(value.as_any())
}

/// A hasher for `TypeId` keys: type IDs are already well distributed.
#[derive(Default)]
struct IdHasher(u64);

impl Hasher for IdHasher {
    fn finish(&self) -> u64 {
        self.0
    }
    fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.0 = self.0.rotate_left(8) ^ u64::from(b);
        }
    }
    #[inline(always)]
    fn write_u64(&mut self, i: u64) {
        self.0 = self.0.rotate_left(32) ^ i;
    }
}

type IdMap<K, V> = HashMap<K, V, BuildHasherDefault<IdHasher>>;

// Built-in facts use plain function pointers. Public registrations can also
// carry state or consume the owning box to preserve reference identity.
enum ConvertFn {
    Borrowed(BorrowedConversion),
    StaticBox(fn(&BoxedValue) -> Option<BoxedValue>),
    Boxed(Rc<dyn Fn(&BoxedValue) -> Option<BoxedValue>>),
    FromRoot(FromObjectFn),
    Number(fn(&dyn std::any::Any, bool) -> Option<BoxedValue>, bool),
}

// Keep this small ownership snapshot inline on conversion paths. Size-focused
// PGO can outline a derived clone into an extra call and temporary copy.
impl Clone for ConvertFn {
    #[inline(always)]
    fn clone(&self) -> Self {
        match self {
            Self::Borrowed(f) => Self::Borrowed(f.clone()),
            Self::StaticBox(f) => Self::StaticBox(*f),
            Self::Boxed(f) => Self::Boxed(Rc::clone(f)),
            Self::FromRoot(f) => Self::FromRoot(*f),
            Self::Number(f, nullable) => Self::Number(*f, *nullable),
        }
    }
}

impl ConvertFn {
    fn apply(&self, value: &BoxedValue) -> Option<BoxedValue> {
        match self {
            Self::Borrowed(f) => f.apply(value.as_any()),
            Self::StaticBox(f) => f(value),
            Self::Boxed(f) => f(value),
            Self::FromRoot(f) => f(value.downcast_ref::<Ref<FerroObject>>()?),
            Self::Number(f, nullable) => f(value.as_any(), *nullable),
        }
    }

    fn borrowed(&self) -> Option<&BorrowedConversion> {
        match self {
            Self::Borrowed(f) => Some(f),
            _ => None,
        }
    }
}

#[derive(Clone)]
enum BorrowedConversion {
    Static(fn(&dyn std::any::Any) -> Option<BoxedValue>),
    Shared(AnyConvertFn),
}

impl BorrowedConversion {
    fn apply(&self, value: &dyn std::any::Any) -> Option<BoxedValue> {
        match self {
            Self::Static(f) => f(value),
            Self::Shared(f) => f(value),
        }
    }
}

// In the common case all applicable views of a conversion share one entry.
// Independently replacing one view preserves the previous callbacks for the
// other views. Only overlapping registrations need secondary storage.
enum Registration {
    Conversion(ConvertFn),
    Cast(ConvertFn),
    Overrides(Box<OverrideRoutes>),
}

struct OverrideRoutes {
    conversion: ConvertFn,
    cast: ConvertFn,
    borrowed: Option<BorrowedConversion>,
}

impl Registration {
    fn conversion(&self) -> &ConvertFn {
        match self {
            Self::Conversion(f) | Self::Cast(f) => f,
            Self::Overrides(routes) => &routes.conversion,
        }
    }

    fn cast(&self) -> Option<&ConvertFn> {
        match self {
            Self::Conversion(_) => None,
            Self::Cast(f) => Some(f),
            Self::Overrides(routes) => Some(&routes.cast),
        }
    }

    fn borrowed(&self) -> Option<&BorrowedConversion> {
        match self {
            Self::Conversion(_) => None,
            Self::Cast(f) => f.borrowed(),
            Self::Overrides(routes) => routes.borrowed.as_ref(),
        }
    }
}

type AnyConvertFn = Rc<dyn Fn(&dyn std::any::Any) -> Option<BoxedValue>>;
type DisplayFn = fn(&dyn AnyValue) -> String;
type UnwrapFn = fn(&dyn AnyValue) -> Option<BoxedValue>;
type NullFn = fn() -> BoxedValue;
type ObjectFn = fn(&dyn AnyValue) -> Option<Ref<FerroObject>>;
type FromObjectFn = fn(&Ref<FerroObject>) -> Option<BoxedValue>;
// Default declarations use a statically known projection and need no owned
// closure. Explicit registrations retain their independently replaceable
// callback. Both variants are cloned out of the registry before user code runs.
#[derive(Clone)]
enum InterfaceFn {
    Static(fn(&Ref<FerroObject>) -> Option<BoxedValue>),
    Dynamic(Rc<dyn Fn(&Ref<FerroObject>) -> Option<BoxedValue>>),
}

impl InterfaceFn {
    #[inline]
    fn apply(&self, object: &Ref<FerroObject>) -> Option<BoxedValue> {
        match self {
            Self::Static(convert) => convert(object),
            Self::Dynamic(convert) => convert(object),
        }
    }
}
type ReferenceIdentityFn = Rc<dyn Fn(&dyn AnyValue) -> Option<*const ()>>;
type InterfaceObjectFn = Rc<dyn Fn(&dyn AnyValue) -> Option<Ref<FerroObject>>>;
type OrderingFn = Rc<dyn Fn(&dyn AnyValue, &dyn AnyValue) -> Option<std::cmp::Ordering>>;

struct NullableType {
    inner: ValueType,
    unwrap: UnwrapFn,
    null: NullFn,
}

#[derive(Default)]
struct Registry {
    display: IdMap<TypeId, DisplayFn>,
    nullable: IdMap<TypeId, NullableType>,
    objects: IdMap<TypeId, (ObjectFn, FromObjectFn, &'static TypeInfo)>,
    /// Model types: values whose box is the shared object itself.
    references: IdMap<TypeId, ()>,
    /// `Rc<T>` of a model type `T` → `T`.
    reference_handles: IdMap<TypeId, TypeId>,
    /// A model type `T` → `Rc<T>`.
    reference_objects: IdMap<TypeId, TypeId>,
    /// Typed interface/class views of an enclosing reference object's identity.
    reference_identities: IdMap<TypeId, ReferenceIdentityFn>,
    conversions: IdMap<(TypeId, TypeId), Registration>,
    /// `ElementRef<T>` and `Option<ElementRef<T>>` → the class `T` and
    /// whether the type is the nullable form: how the emitter of Rust source
    /// names the type.
    #[cfg(feature = "compiler-metadata")]
    element_refs: IdMap<TypeId, (&'static TypeInfo, bool)>,
    /// The pairs of types of which a reference to the first coerces to a
    /// reference to the second ([`ValueTypes::register_deref`]): what the
    /// emitter of Rust source may write as `&value`.
    #[cfg(feature = "compiler-metadata")]
    derefs: IdMap<(TypeId, TypeId), ()>,
    /// `ElementRef<T>` → the element it refers to as an object, and the
    /// reference to an object.
    element_ref_objects: IdMap<TypeId, (ObjectFn, FromObjectFn)>,
    /// Interface handle type → the classes whose handles convert to it.
    interfaces: IdMap<TypeId, Vec<(&'static TypeInfo, InterfaceFn)>>,
    /// Interface handle type → the object of the object model behind a
    /// handle ([`ValueTypes::register_interface_object`]).
    interface_objects: IdMap<TypeId, InterfaceObjectFn>,
    /// The order of the values of a type ([`ValueTypes::register_ordering`]).
    orderings: IdMap<TypeId, OrderingFn>,
}

/// A registered cast of a reference type that applies to another form of
/// the source or of the target: the cast between the forms of the source
/// (if needed), the registered cast, the cast between the forms of the
/// target (if needed).
type ReferenceCast = (Option<ConvertFn>, ConvertFn, Option<ConvertFn>);

impl Registry {
    fn cast(&self, key: &(TypeId, TypeId)) -> Option<&ConvertFn> {
        self.conversions.get(key)?.cast()
    }

    fn nullable_inner(&self, id: &TypeId) -> Option<ValueType> {
        self.nullable.get(id).map(|facts| facts.inner)
    }

    fn set_cast(&mut self, key: (TypeId, TypeId), cast: ConvertFn) {
        let previous = self.conversions.get(&key).and_then(Registration::borrowed);
        let registration = match (cast.borrowed(), previous) {
            (None, Some(borrowed)) => Registration::Overrides(Box::new(OverrideRoutes {
                conversion: cast.clone(), cast, borrowed: Some(borrowed.clone()),
            })),
            _ => Registration::Cast(cast),
        };
        self.conversions.insert(key, registration);
    }

    fn set_conversion(&mut self, key: (TypeId, TypeId), conversion: ConvertFn) {
        let registration = match self.conversions.get(&key).and_then(|r| Some((r.cast()?, r.borrowed()))) {
            Some((cast, borrowed)) => Registration::Overrides(Box::new(OverrideRoutes {
                conversion, cast: cast.clone(), borrowed: borrowed.cloned(),
            })),
            None => Registration::Conversion(conversion),
        };
        self.conversions.insert(key, registration);
    }

    /// The other form of a reference type: the handle `Rc<T>` of the object
    /// form `T`, and the reverse.
    fn other_reference_form(&self, id: TypeId) -> Option<TypeId> {
        self.reference_handles.get(&id).or_else(|| self.reference_objects.get(&id)).copied()
    }

    /// The assignability cast registered between any form of the reference
    /// type `from` (the object `A`, its handle `Rc<A>`) and any form of
    /// `to`, whichever forms it was registered for.
    fn reference_cast(&self, from: TypeId, to: TypeId) -> Option<ReferenceCast> {
        let from_other = self.other_reference_form(from);
        let to_other = self.other_reference_form(to);
        if from_other.is_none() && to_other.is_none() {
            return None;
        }
        for source in [Some(from), from_other].into_iter().flatten() {
            for target in [Some(to), to_other].into_iter().flatten() {
                if (source, target) == (from, to) || source == target {
                    continue;
                }
                let Some(cast) = self.cast(&(source, target)) else { continue };
                let before = match source == from {
                    true => None,
                    false => Some(self.cast(&(from, source))?.clone()),
                };
                let after = match target == to {
                    true => None,
                    false => Some(self.cast(&(target, to))?.clone()),
                };
                return Some((before, cast.clone(), after));
            }
        }
        None
    }

    /// The conversion to the interface handle `interface` declared by the
    /// most derived class that `class` is or derives from.
    fn interface_cast(&self, interface: TypeId, class: &'static TypeInfo) -> Option<&InterfaceFn> {
        let mut best: Option<&(&'static TypeInfo, InterfaceFn)> = None;
        for entry in self.interfaces.get(&interface)? {
            if entry.0.is_assignable_from(class) && best.is_none_or(|b| b.0.is_assignable_from(entry.0)) {
                best = Some(entry);
            }
        }
        best.map(|entry| &entry.1)
    }
}

crate::ferro_thread_local! {
    static REGISTRY: RefCell<Option<Registry>> = const { RefCell::new(None) };
    /// Registrations made before the table was first used on the thread.
    static DEFERRED: RefCell<Vec<fn()>> = const { RefCell::new(Vec::new()) };
}

/// Registration functions that apply to every thread ([`ValueTypes::register_global`]).
static GLOBAL: std::sync::Mutex<Vec<fn()>> = std::sync::Mutex::new(Vec::new());
/// The length of [`GLOBAL`], readable without the lock.
static GLOBAL_LEN: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

crate::ferro_thread_local! {
    /// How many of the [`GLOBAL`] registrations ran on the thread.
    static GLOBAL_APPLIED: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// Runs the process-wide registrations the thread has not run yet.
#[cold]
fn apply_global(applied: usize) {
    let pending: Vec<fn()> = {
        let global = GLOBAL.lock().unwrap_or_else(|e| e.into_inner());
        // Set first: a registration uses the table itself.
        GLOBAL_APPLIED.set(global.len());
        global[applied.min(global.len())..].to_vec()
    };
    for register in pending {
        register();
    }
}

fn with_registry<R>(f: impl FnOnce(&mut Registry) -> R) -> R {
    let initialized = REGISTRY.with(|r| r.borrow().is_some());
    if !initialized {
        REGISTRY.with(|r| *r.borrow_mut() = Some(Registry::default()));
        register_defaults();
        for register in DEFERRED.take() {
            register();
        }
    }
    let applied = GLOBAL_APPLIED.get();
    if applied != GLOBAL_LEN.load(std::sync::atomic::Ordering::Acquire) {
        apply_global(applied);
    }
    REGISTRY.with(|r| f(r.borrow_mut().as_mut().expect("registry is initialized")))
}

// The insertions of the registration functions. The registration functions
// are instantiated once per registered type; what they do with the table
// does not depend on the type, so it lives here, compiled once.

fn insert_display(id: TypeId, display: DisplayFn) {
    with_registry(|r| {
        r.display.insert(id, display);
    });
}

/// Typed operations for one nullable value in the binding registry.
#[derive(Clone, Copy)]
pub struct NullableRegistration {
    inner: fn() -> ValueType,
    nullable: fn() -> TypeId,
    unwrap: UnwrapFn,
    null: NullFn,
    wrap: fn(&dyn std::any::Any) -> Option<BoxedValue>,
}

impl NullableRegistration {
    /// Describes the conversions between `T`, `Option<T>` and a boxed null.
    pub const fn of<T: PropertyValue>() -> Self {
        Self {
            inner: ValueType::of::<T>,
            nullable: TypeId::of::<Option<T>>,
            unwrap: |value| value.downcast_ref::<Option<T>>()?.as_ref()
                .map(|item| Rc::new(item.clone()) as BoxedValue),
            null: || Rc::new(None::<T>),
            wrap: |value| Some(Rc::new(Some(value.downcast_ref::<T>()?.clone()))),
        }
    }
}

fn insert_cast(key: (TypeId, TypeId), cast: ConvertFn) {
    with_registry(|r| r.set_cast(key, cast));
}

fn insert_conversion(key: (TypeId, TypeId), conversion: ConvertFn) {
    with_registry(|r| r.set_conversion(key, conversion));
}

#[inline(never)]
fn insert_object(id: TypeId, nullable_id: TypeId, as_object: ObjectFn, restore: FromObjectFn,
                 restore_nullable: FromObjectFn, class: &'static TypeInfo) {
    with_registry(|r| {
        r.objects.insert(id, (as_object, restore, class));
        let root = TypeId::of::<Ref<FerroObject>>();
        r.set_conversion((root, id), ConvertFn::FromRoot(restore));
        // The root's own nullable conversion is the identical wrapping cast
        // already installed by register_nullable.
        if id != root {
            r.set_conversion((root, nullable_id), ConvertFn::FromRoot(restore_nullable));
        }
    });
}

// The four casts share the same registry policy for every reference model.
struct ReferenceOperations {
    register_identity: fn(),
    unwrap: UnwrapFn,
    null: NullFn,
    object_to_nullable: fn(&BoxedValue) -> Option<BoxedValue>,
    object_to_handle: fn(&BoxedValue) -> Option<BoxedValue>,
    handle_to_object: fn(&BoxedValue) -> Option<BoxedValue>,
    handle_to_nullable: fn(&BoxedValue) -> Option<BoxedValue>,
}

#[inline(never)]
fn install_reference(object: ValueType, handle: TypeId, nullable: TypeId, ops: &ReferenceOperations) {
    let id = object.id();
    if with_registry(|r| r.references.insert(id, ()).is_some()) {
        return;
    }
    (ops.register_identity)();
    with_registry(|r| {
        r.nullable.insert(nullable, NullableType { inner: object, unwrap: ops.unwrap, null: ops.null });
        r.reference_handles.insert(handle, id);
        r.reference_objects.insert(id, handle);
        r.set_cast((id, nullable), ConvertFn::StaticBox(ops.object_to_nullable));
        r.set_cast((id, handle), ConvertFn::StaticBox(ops.object_to_handle));
        r.set_cast((handle, id), ConvertFn::StaticBox(ops.handle_to_object));
        r.set_cast((handle, nullable), ConvertFn::StaticBox(ops.handle_to_nullable));
    });
}

// A weak element reference has the same registration policy for every class.
// Only projection, boxing and weak-handle operations depend on the class.
// Keep those leaves as static functions instead of allocating an Rc<dyn Fn>
// and its invocation/destruction adapters for each built-in conversion.
struct ElementReferenceOperations {
    as_object: ObjectFn,
    from_object: FromObjectFn,
    from_root: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    from_root_to_nullable: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    from_handle: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    from_handle_to_nullable: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    from_nullable_handle: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    to_handle: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    to_nullable_handle: fn(&dyn std::any::Any) -> Option<BoxedValue>,
    nullable_to_nullable_handle: fn(&dyn std::any::Any) -> Option<BoxedValue>,
}

#[inline(never)]
fn install_element_reference(
    element: TypeId,
    nullable_element: TypeId,
    handle: TypeId,
    nullable_handle: TypeId,
    _class: &'static TypeInfo,
    ops: &ElementReferenceOperations,
) {
    with_registry(|r| {
        r.element_ref_objects.insert(element, (ops.as_object, ops.from_object));
        #[cfg(feature = "compiler-metadata")]
        {
            r.element_refs.insert(element, (_class, false));
            r.element_refs.insert(nullable_element, (_class, true));
        }
        r.set_cast((handle, element), ConvertFn::Borrowed(BorrowedConversion::Static(ops.from_handle)));
        r.set_cast((handle, nullable_element), ConvertFn::Borrowed(BorrowedConversion::Static(ops.from_handle_to_nullable)));
        r.set_cast((nullable_handle, nullable_element), ConvertFn::Borrowed(BorrowedConversion::Static(ops.from_nullable_handle)));
        let root = TypeId::of::<Ref<FerroObject>>();
        // For T = FerroObject these keys overlap the casts above. Retain the
        // separate assignability/borrowed views just as public registration does.
        r.set_conversion((root, element), ConvertFn::Borrowed(BorrowedConversion::Static(ops.from_root)));
        r.set_conversion((root, nullable_element), ConvertFn::Borrowed(BorrowedConversion::Static(ops.from_root_to_nullable)));
        r.set_conversion((element, handle), ConvertFn::Borrowed(BorrowedConversion::Static(ops.to_handle)));
        r.set_cast((element, nullable_handle), ConvertFn::Borrowed(BorrowedConversion::Static(ops.to_nullable_handle)));
        r.set_cast((nullable_element, nullable_handle), ConvertFn::Borrowed(BorrowedConversion::Static(ops.nullable_to_nullable_handle)));
    });
}

fn insert_interface(interface: TypeId, class: &'static TypeInfo, convert: InterfaceFn) {
    with_registry(|r| {
        let entries = r.interfaces.entry(interface).or_default();
        match entries.iter_mut().find(|e| std::ptr::eq(e.0, class)) {
            Some(entry) => entry.1 = convert,
            None => entries.push((class, convert)),
        }
    });
}

fn insert_ordering(id: TypeId, compare: OrderingFn) {
    with_registry(|r| {
        r.orderings.insert(id, compare);
    });
}

/// The per-thread table of value type knowledge used by untyped bindings.
pub struct ValueTypes;

impl ValueTypes {
    /// Runs `register` (a function that makes registrations with this table)
    /// now if the table is in use on the thread, and otherwise when it is
    /// first used. This is how classes register their handle types: a
    /// thread that never converts untyped values does not build the table.
    pub fn register_deferred(register: fn()) {
        if REGISTRY.with(|r| r.borrow().is_some()) {
            register();
        } else {
            DEFERRED.with(|d| d.borrow_mut().push(register));
        }
    }

    /// Adds a registration function that applies to EVERY thread: it runs on
    /// each thread when the thread next uses the table (the calling thread
    /// included), whether the thread first used the table before or after
    /// this call. Adding the same function again does nothing.
    ///
    /// This is how a crate registers the value types it declares metadata
    /// for (from its `register_types()`): the per-thread table then knows
    /// them on whatever thread untyped values are converted, with no
    /// per-thread call.
    pub fn register_global(register: fn()) {
        let mut global = GLOBAL.lock().unwrap_or_else(|e| e.into_inner());
        if !global.iter().any(|f| std::ptr::fn_addr_eq(*f, register)) {
            global.push(register);
            GLOBAL_LEN.store(global.len(), std::sync::atomic::Ordering::Release);
        }
    }

    /// Registers `T` as convertible to text through its [`fmt::Display`]
    /// implementation (the `ToString()` of the value), and to `String`.
    pub fn register_display<T: fmt::Display + 'static>() {
        fn display<T: fmt::Display + 'static>(value: &dyn AnyValue) -> String {
            value.downcast_ref::<T>().map(T::to_string).unwrap_or_default()
        }
        insert_display(TypeId::of::<T>(), display::<T>);
    }

    /// Registers `Option<T>` as the nullable form of `T`: untyped bindings
    /// treat `None` as null and `Some(v)` as `v`, and convert a `T` (or null)
    /// to `Option<T>` when a target requires it.
    pub fn register_nullable<T: PropertyValue>() {
        Self::register_nullable_types(&const { [NullableRegistration::of::<T>()] });
    }

    /// Registers the nullable forms in declaration order on the current thread.
    pub fn register_nullable_types(types: &[NullableRegistration]) {
        with_registry(|registry| {
            for entry in types {
                let inner = (entry.inner)();
                let nullable = (entry.nullable)();
                registry.set_cast((inner.id(), nullable), ConvertFn::Borrowed(BorrowedConversion::Static(entry.wrap)));
                registry.nullable.insert(nullable, NullableType { inner, unwrap: entry.unwrap, null: entry.null });
            }
        });
    }

    /// Registers an assignability cast: values of `TFrom` are values of
    /// `TTo` (the same value, seen as a wider type), as opposed to values
    /// that can merely be converted to it. A cast is also a conversion.
    pub fn register_cast<TFrom: 'static, TTo: PropertyValue>(cast: impl Fn(&TFrom) -> TTo + 'static) {
        let convert: AnyConvertFn =
            Rc::new(move |value| value.downcast_ref::<TFrom>().map(|v| Rc::new(cast(v)) as BoxedValue));
        insert_cast((TypeId::of::<TFrom>(), TypeId::of::<TTo>()), ConvertFn::Borrowed(BorrowedConversion::Shared(convert)));
    }

    /// States that the Rust type `TFrom` dereferences to `TTo`: `&TFrom`
    /// coerces to `&TTo` (a named collection that implements `Deref` down to
    /// the list it derives from). `deref` is that coercion, written `|c| c`:
    /// the call compiles exactly when the coercion does, so the fact cannot
    /// be stated of two types it does not hold for.
    ///
    /// The fact is recorded for the emitter of Rust source, which writes the
    /// instance of a member the base declares as `&value` only for a pair
    /// stated here; it changes no conversion (the cast of the pair is
    /// registered with [`register_cast`](Self::register_cast)). Without the
    /// `compiler-metadata` feature nothing is recorded.
    pub fn register_deref<TFrom: 'static, TTo: 'static>(deref: fn(&TFrom) -> &TTo) {
        let _ = deref;
        #[cfg(feature = "compiler-metadata")]
        with_registry(|r| {
            r.derefs.insert((TypeId::of::<TFrom>(), TypeId::of::<TTo>()), ());
        });
    }

    /// Whether `from` is registered as dereferencing to `to`
    /// ([`register_deref`](Self::register_deref)).
    #[cfg(feature = "compiler-metadata")]
    pub fn dereferences(from: TypeId, to: TypeId) -> bool {
        with_registry(|r| r.derefs.get(&(from, to)).is_some())
    }

    /// The number of pairs registered with
    /// [`register_deref`](Self::register_deref).
    #[cfg(feature = "compiler-metadata")]
    pub fn dereference_count() -> usize {
        with_registry(|r| r.derefs.len())
    }

    /// Registers a conversion between two value types. Returning `None`
    /// means the value cannot be converted.
    pub fn register_conversion<TFrom: 'static, TTo: PropertyValue>(convert: impl Fn(&TFrom) -> Option<TTo> + 'static) {
        insert_conversion(
            (TypeId::of::<TFrom>(), TypeId::of::<TTo>()),
            ConvertFn::Borrowed(BorrowedConversion::Shared(Rc::new(move |v| v.downcast_ref::<TFrom>().and_then(&convert).map(|v| Rc::new(v) as BoxedValue)))),
        );
    }

    /// Registers the conversion of text to `T` through `parse`, the
    /// equivalent of a type converter from string.
    pub fn register_parse<T: PropertyValue>(parse: fn(&str) -> Option<T>) {
        Self::register_conversion::<String, T>(move |s| parse(s));
    }

    /// Registers the handle type of class `T` (`Ref<T>`), so that untyped
    /// bindings recognise values of it as objects with registered properties
    /// and can convert them to base class handles and nullable handles.
    pub fn register_object<T: ObjectType>() {
        fn as_object<T: ObjectType>(value: &dyn AnyValue) -> Option<Ref<FerroObject>> {
            value.downcast_ref::<Ref<T>>().map(|v| v.clone().upcast())
        }
        fn from_object<T: ObjectType>(value: &Ref<FerroObject>) -> Option<BoxedValue> {
            Some(Rc::new(value.cast::<T>()?))
        }
        fn from_nullable_object<T: ObjectType>(value: &Ref<FerroObject>) -> Option<BoxedValue> {
            Some(Rc::new(Some(value.cast::<T>()?)))
        }
        Self::register_nullable::<Ref<T>>();
        insert_object(TypeId::of::<Ref<T>>(), TypeId::of::<Option<Ref<T>>>(), as_object::<T>,
                      from_object::<T>, from_nullable_object::<T>, T::TYPE);
    }

    /// Registers the element reference type of class `T`
    /// ([`ElementRef<T>`](crate::ElementRef)): the value type of properties
    /// that point at an element they do not own. Handles (`Ref<T>`,
    /// `Option<Ref<T>>`, object handles) convert to it and it converts back
    /// to handles, in bindings and in untyped property access, so that
    /// such a property behaves like one of type `Ref<T>`.
    pub fn register_element_ref<T: ObjectType>() {
        use crate::ElementRef;

        Self::register_nullable::<ElementRef<T>>();
        fn element<T: ObjectType>(value: &dyn AnyValue) -> Option<Ref<FerroObject>> {
            let element = value.downcast_ref::<ElementRef<T>>()?.get()?;
            let object: &FerroObject = (*element).upcast();
            Some(object.to_ref())
        }
        fn reference<T: ObjectType>(object: &Ref<FerroObject>) -> Option<BoxedValue> {
            object.cast::<T>().map(|element| Rc::new(ElementRef::of(&element)) as BoxedValue)
        }
        install_element_reference(
            TypeId::of::<ElementRef<T>>(),
            TypeId::of::<Option<ElementRef<T>>>(),
            TypeId::of::<Ref<T>>(),
            TypeId::of::<Option<Ref<T>>>(),
            T::TYPE,
            &const { ElementReferenceOperations {
                as_object: element::<T>,
                from_object: reference::<T>,
                from_root: |value| {
                    let element = value.downcast_ref::<Ref<FerroObject>>()?.cast::<T>()?;
                    Some(Rc::new(ElementRef::of(&element)))
                },
                from_root_to_nullable: |value| {
                    let element = value.downcast_ref::<Ref<FerroObject>>()?.cast::<T>()?;
                    Some(Rc::new(Some(ElementRef::of(&element))))
                },
                from_handle: |value| Some(Rc::new(ElementRef::of(value.downcast_ref::<Ref<T>>()?))),
                from_handle_to_nullable: |value| {
                    Some(Rc::new(Some(ElementRef::of(value.downcast_ref::<Ref<T>>()?))))
                },
                from_nullable_handle: |value| {
                    Some(Rc::new(ElementRef::from_nullable(value.downcast_ref::<Option<Ref<T>>>()?.clone())))
                },
                to_handle: |value| Some(Rc::new(value.downcast_ref::<ElementRef<T>>()?.get()?)),
                to_nullable_handle: |value| Some(Rc::new(value.downcast_ref::<ElementRef<T>>()?.get())),
                nullable_to_nullable_handle: |value| {
                    Some(Rc::new(ElementRef::resolve(value.downcast_ref::<Option<ElementRef<T>>>()?)))
                },
            } },
        );
    }

    /// Converts a borrowed untyped value to the value type `target` of a
    /// property that was given a value of another type, if a conversion for
    /// untyped property access is registered (element references accept
    /// handles this way).
    pub fn try_convert_for_property(value: &dyn std::any::Any, target: TypeId) -> Option<BoxedValue> {
        let key = (<dyn std::any::Any>::type_id(value), target);
        let f = with_registry(|r| r.conversions.get(&key).and_then(Registration::borrowed).cloned());
        f.and_then(|f| f.apply(value))
    }

    /// Converts a borrowed untyped value to the value type `target` with the
    /// conversions the managed original allows implicitly when a property is
    /// set through its untyped route (`TypeUtilities.TryConvertImplicit`):
    /// an assignability cast (a value to its nullable form, a handle to a
    /// base class or interface handle, an element to an element reference)
    /// and the implicit numeric conversions of the language. A conversion
    /// that can lose the value (a narrowing one, parsing text) is not among
    /// them; neither is a user-defined implicit operator, which the managed
    /// original finds by reflection: a type states such a conversion with
    /// [`ValueTypes::register_cast`].
    pub fn try_convert_implicit(value: &dyn std::any::Any, target: TypeId) -> Option<BoxedValue> {
        Self::try_convert_for_property(value, target).or_else(|| implicit_numeric(value, target))
    }

    /// Registers the interface handle type `I` (for example
    /// `Rc<dyn IBrush>`) as one that handles of class `T`, and of every
    /// class deriving from it, convert to. The conversion is an
    /// assignability cast, like the cast of a handle to a base class handle,
    /// and also applies to the nullable form `Option<I>`.
    ///
    /// Classes state their interfaces with `ferro_class_info!`, which calls
    /// this when the class is initialised. When several classes of a chain
    /// register the same interface, the most derived one converts.
    pub fn register_interface<T: ObjectType, I: PropertyValue>(cast: fn(Ref<T>) -> I) {
        let convert = InterfaceFn::Dynamic(
            Rc::new(move |o: &Ref<FerroObject>| o.cast::<T>().map(|o| Rc::new(cast(o)) as BoxedValue)),
        );
        insert_interface(TypeId::of::<I>(), T::TYPE, convert);
        Self::register_nullable::<I>();
    }

    /// Installs the statically known conversion of a default interface
    /// declaration. Explicit `I => expression` declarations use the public
    /// registration API so the expression still runs at registration time.
    #[doc(hidden)]
    pub fn __register_interface_default<T: ObjectType, I: PropertyValue>()
    where
        Ref<T>: Into<I>,
    {
        fn convert<T: ObjectType, I: PropertyValue>(object: &Ref<FerroObject>) -> Option<BoxedValue>
        where
            Ref<T>: Into<I>,
        {
            Some(Rc::new(Into::<I>::into(object.cast::<T>()?)))
        }
        insert_interface(TypeId::of::<I>(), T::TYPE, InterfaceFn::Static(convert::<T, I>));
        Self::register_nullable::<I>();
    }

    /// Converts an object to the interface handle type `target` (or its
    /// nullable form), if the class of the object declares the interface.
    fn object_to_interface(object: &Ref<FerroObject>, target: ValueType) -> Option<BoxedValue> {
        Self::object_to_interface_id(object, target.id())
    }

    fn object_to_interface_id(object: &Ref<FerroObject>, target: TypeId) -> Option<BoxedValue> {
        let class = object.get_type();
        let (cast, wrap) = with_registry(|r| {
            if let Some(cast) = r.interface_cast(target, class) {
                return (Some(cast.clone()), None);
            }
            let Some(inner) = r.nullable_inner(&target) else {
                return (None, None);
            };
            (r.interface_cast(inner.id(), class).cloned(), r.cast(&(inner.id(), target)).cloned())
        });
        let value = cast?.apply(object)?;
        match wrap {
            Some(wrap) => wrap.apply(&value),
            None if value_type_id(&*value) == target => Some(value),
            None => None,
        }
    }

    /// Registers the conversion of handles of class `T` to handles of its
    /// base class `TBase`.
    pub fn register_upcast<T: ObjectType + Upcast<TBase>, TBase: ObjectType>() {
        let from = TypeId::of::<Ref<T>>();
        insert_cast((from, TypeId::of::<Ref<TBase>>()), ConvertFn::Borrowed(BorrowedConversion::Static(|value| {
            Some(Rc::new(value.downcast_ref::<Ref<T>>()?.clone().upcast::<TBase>()))
        })));
        insert_cast((from, TypeId::of::<Option<Ref<TBase>>>()), ConvertFn::Borrowed(BorrowedConversion::Static(|value| {
            Some(Rc::new(Some(value.downcast_ref::<Ref<T>>()?.clone().upcast::<TBase>())))
        })));
    }

    /// Normalises a value read from a property for use in a binding chain:
    /// a nullable (`Option<T>`) value becomes null or the contained value.
    pub fn normalize(value: BoxedValue) -> Option<BoxedValue> {
        let mut value = value;
        loop {
            let id = value_type_id(&*value);
            if id == TypeId::of::<Option<BoxedValue>>() {
                match value.downcast_ref::<Option<BoxedValue>>() {
                    Some(Some(inner)) => {
                        let inner = inner.clone();
                        value = inner;
                        continue;
                    }
                    _ => return None,
                }
            }
            let unwrap = with_registry(|r| r.nullable.get(&id).map(|facts| facts.unwrap));
            return match unwrap {
                Some(unwrap) => unwrap(&*value),
                None => Some(value),
            };
        }
    }

    /// The text form of a value (its `ToString()`): its registered display
    /// form; without one, the dotted full name of its type (the run-time
    /// class of an object of the class hierarchy, the name the metadata of
    /// the type states) or the name of the member for a value of an
    /// enumeration with metadata; only then the Rust type name. Null is
    /// `"(null)"`.
    pub fn to_display_string(value: Option<&BoxedValue>) -> String {
        match value {
            None => "(null)".to_string(),
            Some(v) => Self::try_to_string(&**v).unwrap_or_else(|| (**v).type_name().to_string()),
        }
    }

    /// The text form of a value, if its type has one: its registered
    /// display form, or else the name [`to_display_string`](Self::to_display_string)
    /// describes for a type that is a class of the object model or has
    /// registered metadata. `None` for a type nothing is known about.
    pub fn try_to_string(value: &dyn AnyValue) -> Option<String> {
        if let Some(s) = value.downcast_ref::<String>() {
            return Some(s.clone());
        }
        if let Some(s) = value.downcast_ref::<&'static str>() {
            return Some((*s).to_string());
        }
        let id = value_type_id(&*value);
        let display = with_registry(|r| r.display.get(&id).copied());
        if let Some(display) = display {
            return Some(display(value));
        }
        if let Some(object) = Self::as_object(value) {
            return Some(object.get_type().full_name());
        }
        let markup = crate::metadata::MarkupType::find_by_handle(id)?;
        if markup.kind == crate::metadata::MarkupTypeKind::Enum {
            if let Some(member) = markup.enum_members.iter().find(|member| (*(member.get)()).value_eq(value)) {
                return Some(member.name.to_string());
            }
        }
        Some(markup.full_name())
    }

    /// The dotted full name of a type, as the managed original prints a
    /// type: the name of the runtime library type a primitive mirrors
    /// (`System.Int32`, `System.String`, `System.Object`), the full name of
    /// the class of a handle, the name the registered metadata of the type
    /// states (for any of its handles), ``System.Nullable`1[..]`` for the
    /// nullable form of a value type; the Rust type name for a type nothing
    /// is known about.
    pub fn type_full_name(type_: ValueType) -> String {
        if type_.is_object() {
            return "System.Object".to_string();
        }
        if let Some(name) = primitive_full_name(type_.id()) {
            return name.to_string();
        }
        let (class, inner) = with_registry(|r| {
            (r.objects.get(&type_.id()).map(|o| o.2), r.nullable_inner(&type_.id()))
        });
        if let Some(class) = class {
            return class.full_name();
        }
        if let Some(markup) = crate::metadata::MarkupType::find_by_handle(type_.id()) {
            return markup.full_name();
        }
        if let Some(markup) = crate::metadata::MarkupType::find_by_nullable_handle(type_.id()) {
            return format!("System.Nullable`1[{}]", markup.full_name());
        }
        match inner {
            Some(inner) if inner.is::<String>() => "System.String".to_string(),
            Some(inner) if primitive_full_name(inner.id()).is_some() => {
                format!("System.Nullable`1[{}]", Self::type_full_name(inner))
            }
            Some(inner) => Self::type_full_name(inner),
            None => type_.name().to_string(),
        }
    }

    /// The object form of a value held as the handle `Rc<T>` of a registered
    /// reference type `T` (the box that is the shared object itself); `None`
    /// for every other value.
    pub fn reference_object(value: &BoxedValue) -> Option<BoxedValue> {
        let handle = value_type_id(&**value);
        let cast = with_registry(|r| {
            r.reference_handles.get(&handle).and_then(|object| r.cast(&(handle, *object)).cloned())
        })?;
        cast.apply(value)
    }

    /// Registers the enclosing object identity of a typed view. `identity`
    /// returns the address of the shared object which the view keeps alive,
    /// never a temporary adapter or a value-derived hash. The address is only
    /// compared, never dereferenced. Registration does not change conversions.
    pub fn register_reference_identity<T: 'static>(identity: fn(&T) -> *const ()) {
        let identity: ReferenceIdentityFn = Rc::new(move |value| value.downcast_ref::<T>().map(identity));
        with_registry(|r| { r.reference_identities.insert(TypeId::of::<T>(), identity); });
    }

    /// The identity of the object an untyped value represents. Native objects,
    /// registered interface/class views and Rc<T> handles use their enclosing
    /// object; other boxes retain their own identity, never value equality.
    pub fn reference_identity(value: &BoxedValue) -> *const () {
        if let Some(object) = Self::as_object(&**value) {
            return &*object as *const FerroObject as *const ();
        }
        Self::boxed_reference_identity(value)
    }

    fn boxed_reference_identity(value: &BoxedValue) -> *const () {
        let identity = with_registry(|r| r.reference_identities.get(&value_type_id(&**value)).cloned());
        if let Some(identity) = identity.and_then(|identity| identity(&**value)) {
            return identity;
        }
        let object = Self::reference_object(value).unwrap_or_else(|| value.clone());
        Rc::as_ptr(&object) as *const ()
    }

    /// Whether two non-null boxed values represent the same object instance.
    /// Equal value-type boxes remain distinct objects.
    pub fn reference_equals(first: &BoxedValue, other: &BoxedValue) -> bool {
        if Rc::ptr_eq(first, other) {
            return true;
        }
        // Keep native objects alive through both lookups, including weak element
        // references, and invoke each native projection only once.
        let first_native = Self::as_object(&**first);
        let other_native = Self::as_object(&**other);
        let first_identity = first_native.as_ref().map(|object| &**object as *const FerroObject as *const ())
            .unwrap_or_else(|| Self::boxed_reference_identity(first));
        let other_identity = other_native.as_ref().map(|object| &**object as *const FerroObject as *const ())
            .unwrap_or_else(|| Self::boxed_reference_identity(other));
        first_identity == other_identity
    }

    /// The class `T` of a registered element reference type
    /// ([`register_element_ref`](Self::register_element_ref)) with the id
    /// `id` (`ElementRef<T>`, or `Option<ElementRef<T>>`, the nullable form),
    /// and whether it is the nullable form. For the emitter of Rust source,
    /// which names the type by the class.
    #[cfg(feature = "compiler-metadata")]
    pub fn element_ref_class(id: TypeId) -> Option<(&'static TypeInfo, bool)> {
        with_registry(|r| r.element_refs.get(&id).copied())
    }

    /// Views a value as an object of the class hierarchy, if it is a
    /// registered handle type. Deviation (DEVIATIONS.md, Bindings): a
    /// registered element reference ([`ElementRef<T>`](crate::ElementRef))
    /// is viewed as the element it refers to while that is alive: a value that is one (a `DataContext`
    /// that is an ancestor of its element) is the element to a binding.
    pub fn as_object(value: &dyn AnyValue) -> Option<Ref<FerroObject>> {
        if let Some(o) = value.downcast_ref::<Ref<FerroObject>>() {
            return Some(o.clone());
        }
        let id = value_type_id(&*value);
        let (f, element, interface) = with_registry(|r| {
            (
                r.objects.get(&id).map(|o| o.0),
                r.element_ref_objects.get(&id).map(|e| e.0),
                r.interface_objects.get(&id).cloned(),
            )
        });
        match f.or(element) {
            Some(f) => f(value),
            None => interface.and_then(|f| f(value)),
        }
    }

    /// Registers the interface handle type `I` (for example
    /// `Rc<dyn IFoo>`, the handle of a contract that classes of the object
    /// model implement) as one that holds an object: `as_object` gives the
    /// object behind a handle, `None` for a handle of an implementation that
    /// is not one. Untyped code then sees the object through the handle, as
    /// upstream sees the object whatever the static type of the reference:
    /// [`as_object`](Self::as_object) answers it, so that a content that is
    /// a handle of a control is that control, and a binding converts the
    /// handle to the handles of the class of the object.
    ///
    /// The class states which handles it converts to (`ferro_class_info!`,
    /// `interfaces:`); this is the reverse, stated once by the contract.
    pub fn register_interface_object<I: PropertyValue>(as_object: fn(&I) -> Option<Ref<FerroObject>>) {
        let f: InterfaceObjectFn = Rc::new(move |value: &dyn AnyValue| value.downcast_ref::<I>().and_then(as_object));
        with_registry(|r| {
            r.interface_objects.insert(TypeId::of::<I>(), f);
        });
        Self::register_nullable::<I>();
    }

    /// Registers `T` as a reference (model) type: a type whose instances are
    /// shared objects with identity, boxed as the shared object itself
    /// (`Rc<T>` coerced to a [`BoxedValue`]). Bindings hold such sources
    /// weakly, treat null as a valid value of the type, and convert between
    /// the object and `Rc<T>` / `Option<Rc<T>>` typed properties.
    pub fn register_reference<T: PartialEq + 'static>() {
        fn unwrap<T: PartialEq + 'static>(value: &dyn AnyValue) -> Option<BoxedValue> {
            match value.downcast_ref::<Option<Rc<T>>>() {
                Some(Some(v)) => Some(v.clone() as BoxedValue),
                _ => None,
            }
        }
        fn null<T: PartialEq + 'static>() -> BoxedValue {
            Rc::new(Option::<Rc<T>>::None)
        }
        fn to_rc<T: PartialEq + 'static>(value: &BoxedValue) -> Option<Rc<T>> {
            let any: Rc<dyn std::any::Any> = value.clone();
            any.downcast::<T>().ok()
        }
        install_reference(
            ValueType::of::<T>(),
            TypeId::of::<Rc<T>>(),
            TypeId::of::<Option<Rc<T>>>(),
            &const { ReferenceOperations {
                register_identity: || ValueTypes::register_reference_identity::<Rc<T>>(|v| Rc::as_ptr(v).cast()),
                unwrap: unwrap::<T>,
                null: null::<T>,
                object_to_nullable: |v| to_rc::<T>(v).map(|v| Rc::new(Some(v)) as BoxedValue),
                object_to_handle: |v| to_rc::<T>(v).map(|v| Rc::new(v) as BoxedValue),
                handle_to_object: |v| v.downcast_ref::<Rc<T>>().map(|v| v.clone() as BoxedValue),
                handle_to_nullable: |v| v.downcast_ref::<Rc<T>>().map(|v| Rc::new(Some(v.clone())) as BoxedValue),
            } },
        );
    }

    /// Whether the type is a registered reference (model) type.
    pub fn is_reference(id: TypeId) -> bool {
        with_registry(|r| r.references.contains_key(&id))
    }

    /// Re-creates the registered handle type `id` from a root handle.
    pub(crate) fn from_object(id: TypeId, object: Ref<FerroObject>) -> Option<BoxedValue> {
        if id == TypeId::of::<Ref<FerroObject>>() {
            return Some(Rc::new(object));
        }
        let f = with_registry(|r| r.objects.get(&id).map(|o| o.1).or_else(|| r.element_ref_objects.get(&id).map(|e| e.1)));
        match f {
            Some(restore) => restore(&object),
            // Weak binding sources retain the original interface handle type.
            // Restore it through the class's declared interface facts, including
            // inherited and nullable views, without retaining a strong source.
            None => Self::object_to_interface_id(&object, id),
        }
    }

    /// The type a registered nullable form holds: `T` for `Option<T>` and for
    /// `Option<Rc<T>>`, `None` for any other type.
    pub fn nullable_inner(type_: ValueType) -> Option<ValueType> {
        with_registry(|r| r.nullable_inner(&type_.id()))
    }

    /// Whether `target` accepts null.
    pub fn accepts_null(target: ValueType) -> bool {
        target.is_object()
            || with_registry(|r| r.nullable.contains_key(&target.id()) || r.references.contains_key(&target.id()))
    }

    /// The boxed null of a nullable target type.
    pub fn null_value(target: ValueType) -> Option<BoxedValue> {
        if target.is::<Option<BoxedValue>>() {
            return Some(Rc::new(Option::<BoxedValue>::None));
        }
        let f = with_registry(|r| r.nullable.get(&target.id()).map(|facts| facts.null));
        f.map(|f| f())
    }

    /// Looks up a registered conversion.
    pub fn try_convert_registered(value: &BoxedValue, target: ValueType) -> Option<BoxedValue> {
        let key = (value_type_id(&**value), target.id());
        let f = with_registry(|r| r.conversions.get(&key).map(|r| r.conversion().clone()));
        f.and_then(|f| f.apply(value))
    }

    /// Converts a value to exactly `target`. Returns `None` if no conversion
    /// applies; `Some(None)` (null) is only returned for a null value when
    /// `target` is the untyped "any value" [`BoxedValue`] type or a reference
    /// (model) type.
    ///
    /// The order follows the managed implicit conversion rules: identity,
    /// null to nullable, wrapping into "any value", registered conversions
    /// (which include wrapping into `Option<T>`, numeric conversions, parsing
    /// from text and handle casts), and finally conversion to text.
    pub fn try_convert(value: Option<&BoxedValue>, target: ValueType) -> Option<Option<BoxedValue>> {
        let Some(value) = value else {
            if target.is::<BoxedValue>() || Self::is_reference(target.id()) {
                return Some(None);
            }
            return Self::null_value(target).map(Some);
        };
        let id = value_type_id(&**value);
        if id == target.id() {
            return Some(Some(value.clone()));
        }
        if target.is::<Option<BoxedValue>>() {
            return Some(Some(Rc::new(Some(value.clone()))));
        }
        if target.is::<BoxedValue>() {
            return Some(Some(Rc::new(value.clone())));
        }
        let conversion = with_registry(|r| r.conversions.get(&(id, target.id())).map(|r| r.conversion().clone()));
        if let Some(convert) = conversion {
            if let Some(v) = convert.apply(value) {
                return Some(Some(v));
            }
        } else if let Some(v) = Self::try_cast(value, target) {
            // Assignability includes the object/handle form of a reference and
            // lifting an interface handle to its nullable target. Do not run a
            // registered failing converter twice while looking for that path.
            return Some(Some(v));
        }
        // A nullable source: convert its contents.
        if with_registry(|r| r.nullable.contains_key(&id)) {
            let inner = Self::normalize(value.clone());
            return Self::try_convert(inner.as_ref(), target);
        }
        // Handles convert through the root handle.
        if let Some(object) = Self::as_object(&**value) {
            if id != TypeId::of::<Ref<FerroObject>>() {
                let root: BoxedValue = Rc::new(object.clone());
                if target.is::<Ref<FerroObject>>() {
                    return Some(Some(root));
                }
                if let Some(v) = Self::try_convert_registered(&root, target) {
                    return Some(Some(v));
                }
            }
            // And to the interface handles their class declares.
            if let Some(v) = Self::object_to_interface(&object, target) {
                return Some(Some(v));
            }
        }
        if target.is::<String>() {
            return Self::try_to_string(&**value).map(|s| Some(Rc::new(s) as BoxedValue));
        }
        if target.is::<Option<String>>() {
            return Self::try_to_string(&**value).map(|s| Some(Rc::new(Some(s)) as BoxedValue));
        }
        if let Some(v) = Self::try_convert_enumeration(value, id, target) {
            return Some(Some(v));
        }
        // Text converts to a type that states its conversion from text in
        // its markup metadata: the type converter of the managed original.
        Self::try_parse_text(value, target).map(Some)
    }

    /// The conversions between an enumeration and a number
    /// (`TypeUtilities.TryConvert`): a value that is not of an enumeration
    /// converts to an enumeration when it converts to the underlying type of
    /// the enumeration (`Enum.ToObject(to, value)`), and a value of an
    /// enumeration converts to a numeric type through its numeric value
    /// (`Convert.ChangeType((int)value, to)`). `id` is the type of `value`.
    // Deviation (DEVIATIONS.md, Bindings): a number that is not the value of a member of a
    // plain enumeration does not convert: an enumeration of the port holds its members only.
    fn try_convert_enumeration(value: &BoxedValue, id: TypeId, target: ValueType) -> Option<BoxedValue> {
        use crate::metadata::{MarkupType, MarkupTypeKind};

        let enumeration = |markup: Option<&'static MarkupType>| markup.filter(|markup| markup.kind == MarkupTypeKind::Enum);
        match enumeration(MarkupType::find_by_handle(id)) {
            None => {
                let (markup, is_nullable) = match enumeration(MarkupType::find_by_handle(target.id())) {
                    Some(markup) => (markup, false),
                    None => (enumeration(MarkupType::find_by_nullable_handle(target.id()))?, true),
                };
                let number = Self::try_convert(Some(value), ValueType::of::<i32>())??;
                let member = (markup.enum_from_value?)(i64::from(*number.downcast_ref::<i32>()?))?;
                match is_nullable {
                    true => Self::try_convert_registered(&member, target),
                    false => Some(member),
                }
            }
            Some(markup) => {
                let target_id =
                    with_registry(|r| r.nullable_inner(&target.id()).map_or(target.id(), |inner| inner.id()));
                number_kind(target_id)?;
                let number = match markup.enum_to_value {
                    Some(to_value) => to_value(&**value)?,
                    None => markup.enum_members.iter().find(|member| (member.get)().any_value_eq(&**value))?.value,
                };
                let number: BoxedValue = Rc::new(i32::try_from(number).ok()?);
                Self::try_convert(Some(&number), target)?
            }
        }
    }

    /// Converts a value to exactly `target` as [`try_convert`](Self::try_convert)
    /// does, with the conventions of `culture` for the conversions between
    /// numbers or dates and text (`TypeUtilities.TryConvert(to, value, culture)`,
    /// which converts them with `Convert.ToString(value, culture)` and
    /// `Convert.ChangeType(value, to, culture)`).
    ///
    /// A number or a date becomes text as the culture formats it. Text
    /// becomes a number as the culture writes one: for an integer the signs
    /// of the culture, for a floating point number and a decimal also its
    /// decimal separator and its group separators. Every other conversion
    /// does not depend on the culture, and the invariant culture gives
    /// exactly [`try_convert`](Self::try_convert).
    // Deviation (DEVIATIONS.md, Bindings): the conversion of text to a number is the
    // invariant conversion applied to the text with the symbols of the culture replaced by
    // the invariant ones, not a port of the number parser of the runtime for every type;
    // text is not converted to a date with the culture.
    pub fn try_convert_with_culture(
        value: Option<&BoxedValue>,
        target: ValueType,
        culture: &CultureInfo,
    ) -> Option<Option<BoxedValue>> {
        if culture.is_invariant() {
            return Self::try_convert(value, target);
        }
        let Some(value) = value else {
            return Self::try_convert(None, target);
        };
        let Some(inner) = Self::normalize(value.clone()) else {
            return Self::try_convert(Some(value), target);
        };
        let id = value_type_id(&*inner);
        if id == target.id() {
            return Self::try_convert(Some(value), target);
        }

        if (target.is::<String>() || target.is::<Option<String>>()) && is_formatted_with_culture(id) {
            let text = crate::data::converters::composite_format::format_values_with(
                "{0}",
                std::slice::from_ref(&Some(inner)),
                culture,
            )
            .ok()?;
            return Some(Some(if target.is::<String>() { Rc::new(text) } else { Rc::new(Some(text)) }));
        }

        if let Some(text) = inner.downcast_ref::<String>() {
            let target_id = with_registry(|r| r.nullable_inner(&target.id()).map_or(target.id(), |inner| inner.id()));
            if let Some(kind) = number_kind(target_id) {
                let invariant = number_text_to_invariant(text, kind, &culture.number_format())?;
                let invariant: BoxedValue = Rc::new(invariant);
                return Self::try_convert(Some(&invariant), target);
            }
        }

        Self::try_convert(Some(value), target)
    }

    /// The class of the object model that `type_` is a handle of: `Ref<T>`
    /// or its nullable form `Option<Ref<T>>` of a registered class `T`.
    pub fn class_of(type_: ValueType) -> Option<&'static TypeInfo> {
        with_registry(|r| {
            let id = r.nullable_inner(&type_.id()).map_or(type_.id(), |inner| inner.id());
            r.objects.get(&id).map(|o| o.2)
        })
    }

    /// Converts text to exactly `target` with the conversion from text the
    /// type states in its markup metadata (`parse:`): what the type
    /// converter of the type does in the managed original, where every
    /// conversion of a value to a type (`TypeUtilities.TryConvert`, the
    /// default value converter) consults it. `target` is any handle of a
    /// type with metadata, the nullable form of a value type, or a handle
    /// of a class of the object model (the conversion of the nearest class
    /// that states one applies, as a converter attribute is inherited).
    /// `None` if `value` is not text, the type states no conversion, the
    /// text does not parse or the parsed value is not a value of `target`.
    pub fn try_parse_text(value: &BoxedValue, target: ValueType) -> Option<BoxedValue> {
        use crate::metadata::MarkupType;

        if !value.is::<String>() {
            return None;
        }
        let parse = match Self::class_of(target) {
            Some(class) => {
                let mut current = Some(class);
                let mut found = None;
                while let Some(class) = current {
                    if let Some(parse) = class.markup().and_then(|markup| markup.parse) {
                        found = Some(parse);
                        break;
                    }
                    current = class.base_type();
                }
                found?
            }
            None => {
                let mut current = MarkupType::find_by_handle(target.id())
                    .or_else(|| MarkupType::find_by_nullable_handle(target.id()));
                let mut seen: Vec<&'static MarkupType> = Vec::new();
                let mut found = None;
                while let Some(markup) = current {
                    if seen.iter().any(|known| std::ptr::eq(*known, markup)) {
                        break;
                    }
                    if let Some(parse) = markup.parse {
                        found = Some(parse);
                        break;
                    }
                    seen.push(markup);
                    current = markup.base_type();
                }
                found?
            }
        };
        // A failing conversion is no conversion.
        let parsed = parse(&[Some(value.clone())]).ok()??;
        if ValueType::of_value(&*parsed) == target {
            return Some(parsed);
        }
        Self::try_cast(&parsed, target)
    }

    /// Whether a value of type `from` can be assigned to a location of type
    /// `to` without converting it: the two types are the same, `to` is the
    /// "any value" type, `to` is the nullable form of a type `from` is
    /// assignable to, `from` is a handle of a class derived from the class of
    /// the handle `to`, or a cast between the two is registered
    /// ([`register_cast`](Self::register_cast), [`register_upcast`](Self::register_upcast),
    /// [`register_reference`](Self::register_reference)). A cast registered
    /// for one form of a reference type (the object `A`, its handle `Rc<A>`)
    /// applies to its other forms, and to the forms of its target (`Rc<B>`,
    /// `B`, `Option<Rc<B>>`). Numeric conversions, parsing and conversion to
    /// text are not assignability.
    pub fn is_assignable(from: ValueType, to: ValueType) -> bool {
        if from == to || to.is_object() {
            return true;
        }
        let (direct, from_class, to_class, from_inner, to_inner) = with_registry(|r| {
            (
                r.cast(&(from.id(), to.id())).is_some() || r.reference_cast(from.id(), to.id()).is_some(),
                r.objects.get(&from.id()).map(|o| o.2),
                r.objects.get(&to.id()).map(|o| o.2),
                r.nullable_inner(&from.id()),
                r.nullable_inner(&to.id()),
            )
        });
        if direct {
            return true;
        }
        if let (Some(from_class), Some(to_class)) = (from_class, to_class) {
            return to_class.is_assignable_from(from_class);
        }
        if let Some(from_class) = from_class {
            // A handle is assignable to the interface handles its class
            // declares.
            if with_registry(|r| r.interface_cast(to.id(), from_class).is_some()) {
                return true;
            }
        }
        match (from_inner, to_inner) {
            // Null stays null, a value is assigned as the contained type.
            (Some(inner), Some(_)) => Self::is_assignable(inner, to),
            (None, Some(inner)) => Self::is_assignable(from, inner),
            _ => false,
        }
    }

    /// Casts a value to exactly `target`, performing only the casts that
    /// [`is_assignable`](Self::is_assignable) describes. Returns `None` if
    /// the type of the value is not assignable to `target`, or if the value
    /// is null and `target` is the non-null "any value" type.
    pub fn try_cast(value: &BoxedValue, target: ValueType) -> Option<BoxedValue> {
        let id = value_type_id(&**value);
        if id == target.id() {
            return Some(value.clone());
        }
        if target.is_object() {
            // The untyped form of the value: null or the contents of a
            // nullable, and the object itself for a model handle.
            let mut untyped = Self::normalize(value.clone());
            if let Some(v) = &untyped {
                let handle = value_type_id(&**v);
                let cast = with_registry(|r| {
                    r.reference_handles.get(&handle).and_then(|object| r.cast(&(handle, *object)).cloned())
                });
                if let Some(cast) = cast {
                    untyped = cast.apply(v);
                }
            }
            return if target.is::<Option<BoxedValue>>() {
                Some(Rc::new(untyped))
            } else {
                untyped.map(|v| Rc::new(v) as BoxedValue)
            };
        }
        let (direct, from_class, to_class, from_nullable, to_inner) = with_registry(|r| {
            (
                r.cast(&(id, target.id())).cloned(),
                r.objects.get(&id).map(|o| o.2),
                r.objects.get(&target.id()).map(|o| o.2),
                r.nullable.contains_key(&id),
                r.nullable_inner(&target.id()),
            )
        });
        if let Some(cast) = direct {
            return cast.apply(value);
        }
        if let Some((before, cast, after)) = with_registry(|r| r.reference_cast(id, target.id())) {
            let source = match before {
                Some(before) => before.apply(value)?,
                None => value.clone(),
            };
            let result = cast.apply(&source)?;
            return match after {
                Some(after) => after.apply(&result),
                None => Some(result),
            };
        }
        if let (Some(from_class), Some(to_class)) = (from_class, to_class) {
            if !to_class.is_assignable_from(from_class) {
                return None;
            }
            // Handles are cast through the root handle.
            return Self::from_object(target.id(), Self::as_object(&**value)?);
        }
        if from_class.is_some() {
            if let Some(v) = Self::as_object(&**value).and_then(|o| Self::object_to_interface(&o, target)) {
                return Some(v);
            }
        }
        let inner = to_inner?;
        if from_nullable {
            return match Self::normalize(value.clone()) {
                Some(contents) => Self::try_cast(&contents, target),
                None => Self::null_value(target),
            };
        }
        let contents = Self::try_cast(value, inner)?;
        let wrap = with_registry(|r| r.cast(&(inner.id(), target.id())).cloned())?;
        wrap.apply(&contents)
    }

    /// Compares two untyped values: nulls are equal to each other, values are
    /// equal if they hold the same type and compare equal (handles compare by
    /// identity).
    pub fn identity_equals(a: Option<&BoxedValue>, b: Option<&BoxedValue>) -> bool {
        match (a, b) {
            (None, None) => true,
            (Some(a), Some(b)) => Rc::ptr_eq(a, b) || (**a).value_eq(&**b),
            _ => false,
        }
    }

    /// Registers the order of the values of `T` (the `IComparable` of the
    /// managed original) as its [`PartialOrd`], for [`compare`](Self::compare).
    ///
    /// Like every registration of this table, it applies to the calling
    /// thread; register from a function given to
    /// [`register_global`](Self::register_global) for every thread. The
    /// numbers, booleans, characters, text, the decimal, dates and time
    /// spans are registered by default.
    pub fn register_ordering<T: PartialOrd + 'static>() {
        Self::register_ordering_by::<T>(|a, b| a.partial_cmp(b));
    }

    /// Registers the order of the values of `T` as `compare` (the
    /// `CompareTo` of the managed original), for [`compare`](Self::compare).
    /// `None` from `compare` means the two values are not comparable.
    pub fn register_ordering_by<T: 'static>(compare: impl Fn(&T, &T) -> Option<std::cmp::Ordering> + 'static) {
        let compare: OrderingFn = Rc::new(move |a: &dyn AnyValue, b: &dyn AnyValue| {
            compare(a.downcast_ref::<T>()?, b.downcast_ref::<T>()?)
        });
        insert_ordering(TypeId::of::<T>(), compare);
    }

    /// Whether the values of `type_` have an order for [`compare`](Self::compare):
    /// a registered order, or an enumeration with markup metadata.
    pub fn is_ordered(type_: ValueType) -> bool {
        with_registry(|r| r.orderings.contains_key(&type_.id())) || Self::is_enumeration(type_.id())
    }

    /// Orders two untyped values, as the managed original orders two
    /// `IComparable` operands: the right operand is converted to the type of
    /// the left one (`Convert.ChangeType(right, left.GetType())`) and the
    /// left one compares itself with the result (`left.CompareTo(right)`).
    /// `None` when the values are not comparable: either one is null or of
    /// a type without an order, or the right operand does not convert.
    ///
    /// - Numbers of any primitive type (and the decimal) compare
    ///   numerically: the right operand converts with the rules of
    ///   `Convert.ChangeType` (an integer when it is in range, a floating
    ///   point number rounded to the nearest integer, midpoints to even);
    ///   when it does not convert to the type of the left operand (it is out
    ///   of its range, or not a number for an integer) both compare as
    ///   64-bit floating point numbers. Not-a-number is less than every
    ///   number and equal to itself, as in the managed original.
    /// - Text compares ordinally, by character code.
    /// - Booleans (false before true) and characters compare with each
    ///   other and with the numbers they convert to and from.
    /// - A value of an enumeration with markup metadata compares by its
    ///   numeric value with a value of the same enumeration only.
    /// - A type that registers an order ([`register_ordering`](Self::register_ordering))
    ///   compares with values of its own type, and with values that convert
    ///   to it ([`try_convert`](Self::try_convert)) and have an order too.
    ///
    /// Nullable values compare by their contents.
    // Deviation (DEVIATIONS.md, Bindings): two numbers whose right operand does not convert
    // to the type of the left one compare as 64-bit floating point numbers, where the
    // managed `Convert.ChangeType` fails (an overflow) and the operands are not comparable.
    pub fn compare(a: &BoxedValue, b: &BoxedValue) -> Option<std::cmp::Ordering> {
        let a = Self::ordering_operand(a)?;
        let b = Self::ordering_operand(b)?;
        let a_id = value_type_id(&*a);
        let b_id = value_type_id(&*b);

        // `Convert.ChangeType` to an enumeration type succeeds for a value of
        // that enumeration only.
        if Self::is_enumeration(a_id) {
            if a_id != b_id {
                return None;
            }
            return Some(Self::enumeration_value(&a, a_id)?.cmp(&Self::enumeration_value(&b, b_id)?));
        }

        let (compare, right_is_ordered) =
            with_registry(|r| (r.orderings.get(&a_id).cloned(), r.orderings.contains_key(&b_id)));
        let compare = compare?;
        if a_id == b_id {
            return compare(&*a, &*b);
        }
        if !right_is_ordered && !Self::is_enumeration(b_id) {
            return None;
        }
        match Self::try_convert(Some(&b), ValueType::of_value(&*a)) {
            Some(Some(converted)) => compare(&*a, &*converted),
            _ => Some(float_order(number_as_f64(&*a)?, number_as_f64(&*b)?)),
        }
    }

    /// An operand of [`compare`](Self::compare): the contents of a nullable
    /// or of an "any value" box, text as `String`; `None` for null.
    fn ordering_operand(value: &BoxedValue) -> Option<BoxedValue> {
        let mut value = Self::normalize(value.clone())?;
        if let Some(inner) = value.downcast_ref::<BoxedValue>() {
            let inner = inner.clone();
            value = Self::normalize(inner)?;
        }
        if let Some(text) = value.downcast_ref::<&'static str>() {
            return Some(Rc::new((*text).to_string()));
        }
        Some(value)
    }

    /// Whether `id` is the type of an enumeration with markup metadata.
    fn is_enumeration(id: TypeId) -> bool {
        crate::metadata::MarkupType::find_by_handle(id)
            .is_some_and(|markup| markup.kind == crate::metadata::MarkupTypeKind::Enum)
    }

    /// The numeric value of a value of the enumeration `id`.
    fn enumeration_value(value: &BoxedValue, id: TypeId) -> Option<i64> {
        let markup = crate::metadata::MarkupType::find_by_handle(id)?;
        match markup.enum_to_value {
            Some(to_value) => to_value(&**value),
            None => markup.enum_members.iter().find(|member| (*(member.get)()).value_eq(&**value)).map(|member| member.value),
        }
    }
}

/// The order of two floating point numbers of the managed original
/// (`Double.CompareTo`): not-a-number is less than every number and equal to
/// itself.
fn float_order(a: f64, b: f64) -> std::cmp::Ordering {
    a.partial_cmp(&b).unwrap_or_else(|| a.is_nan().cmp(&b.is_nan()).reverse())
}

/// A number of a primitive numeric type, or the decimal, as a 64-bit floating
/// point number.
fn number_as_f64(value: &dyn AnyValue) -> Option<f64> {
    macro_rules! numbers {
        ($($ty:ty),*) => {
            $(
                if let Some(v) = value.downcast_ref::<$ty>() {
                    return Some(*v as f64);
                }
            )*
        };
    }
    numbers!(f64, f32, i8, i16, i32, i64, u8, u16, u32, u64, isize, usize);
    value.downcast_ref::<crate::utilities::Decimal>().map(|v| v.to_f64())
}

/// The implicit numeric conversions of the managed original
/// (`TypeUtilities.ImplicitConversions`), for the numeric types of the port:
/// each source type converts to the wider types listed for it, and every
/// integer to the decimal. A floating point number does not convert to the
/// decimal implicitly, nor the decimal to anything else.
///
/// The character row of that table names the unsigned 16-bit integer, the
/// 32-bit integers, the signed 64-bit integer, the floating point numbers
/// and the decimal. `Convert.ChangeType` fails for a character and a
/// floating point number or a decimal, and a conversion that fails is no
/// conversion: a character converts to those four integer types. The
/// boolean row names the boolean alone.
fn implicit_numeric(value: &dyn std::any::Any, target: TypeId) -> Option<BoxedValue> {
    use crate::utilities::Decimal;

    if let Some(v) = value.downcast_ref::<char>() {
        let code = u32::from(*v);
        // A character above the 16-bit range is no character of the managed
        // original: it has no 16-bit form.
        if target == TypeId::of::<u16>() {
            return u16::try_from(code).ok().map(|code| Rc::new(code) as BoxedValue);
        }
        if target == TypeId::of::<i32>() {
            return i32::try_from(code).ok().map(|code| Rc::new(code) as BoxedValue);
        }
        if target == TypeId::of::<u32>() {
            return Some(Rc::new(code) as BoxedValue);
        }
        if target == TypeId::of::<i64>() {
            return Some(Rc::new(i64::from(code)) as BoxedValue);
        }
        return None;
    }
    if target == TypeId::of::<Decimal>() {
        macro_rules! integers {
            ($($from:ty),*) => {
                $(
                    if let Some(v) = value.downcast_ref::<$from>() {
                        return Some(Rc::new(Decimal::from(*v)) as BoxedValue);
                    }
                )*
            };
        }
        integers!(i8, u8, i16, u16, i32, u32, i64, u64);
        return None;
    }
    macro_rules! widen {
        ($($from:ty => [$($to:ty),*]);* $(;)?) => {
            $(
                if let Some(v) = value.downcast_ref::<$from>() {
                    $(
                        if target == TypeId::of::<$to>() {
                            return Some(Rc::new(*v as $to) as BoxedValue);
                        }
                    )*
                    return None;
                }
            )*
        };
    }
    widen! {
        i8 => [i16, i32, i64, f32, f64];
        u8 => [i16, u16, i32, u32, i64, u64, f32, f64];
        i16 => [i32, i64, f32, f64];
        u16 => [i32, u32, i64, u64, f32, f64];
        i32 => [i64, f32, f64];
        u32 => [i64, u64, f32, f64];
        i64 => [f32, f64];
        u64 => [f32, f64];
        f32 => [f64];
    }
    None
}

type NumberConversion = fn(&dyn std::any::Any, bool) -> Option<BoxedValue>;

fn number_conversion<F: NumericCast<T> + Copy + 'static, T: PropertyValue>(
    value: &dyn std::any::Any, nullable: bool,
) -> Option<BoxedValue> {
    let converted = value.downcast_ref::<F>()?.cast()?;
    Some(if nullable { Rc::new(Some(converted)) } else { Rc::new(converted) })
}

macro_rules! numeric_conversions {
    ($types:tt) => { numeric_conversions!(@table $types $types) };
    (@table [$($from:ty),*] $targets:tt) => {{
        let types = [$( (TypeId::of::<$from>(), TypeId::of::<Option<$from>>()) ),*];
        const OPERATIONS: &[&[NumberConversion]] = &[$(numeric_conversions!(@row $from $targets)),*];
        with_registry(|r| {
            r.conversions.reserve(types.len() * types.len() * 2);
            for (&(source, _), row) in types.iter().zip(OPERATIONS.iter().copied()) {
                for (&(target, nullable), &operation) in types.iter().zip(row) {
                    r.set_conversion((source, target), ConvertFn::Number(operation, false));
                    r.set_conversion((source, nullable), ConvertFn::Number(operation, true));
                }
            }
        });
    }};
    (@row $from:ty [$($to:ty),*]) => {
        &[$(number_conversion::<$from, $to> as NumberConversion),*]
    };
}

/// Checked numeric conversion with the managed `Convert.ChangeType` rules:
/// integers convert when in range, floating point values round to the nearest
/// even integer.
trait NumericCast<T> {
    fn cast(self) -> Option<T>;
}

macro_rules! int_to_int {
    ($($from:ty => [$($to:ty),*]);*) => {
        $($(
            impl NumericCast<$to> for $from {
                #[inline]
                fn cast(self) -> Option<$to> { <$to>::try_from(self).ok() }
            }
        )*)*
    };
}

macro_rules! int_to_float {
    ($($from:ty),*) => {
        $(
            impl NumericCast<f64> for $from {
                #[inline]
                fn cast(self) -> Option<f64> { Some(self as f64) }
            }
            impl NumericCast<f32> for $from {
                #[inline]
                fn cast(self) -> Option<f32> { Some(self as f32) }
            }
        )*
    };
}

macro_rules! float_to_int {
    ($($to:ty),*) => {
        $(
            impl NumericCast<$to> for f64 {
                fn cast(self) -> Option<$to> {
                    let rounded = self.round_ties_even();
                    if rounded.is_finite() && rounded >= <$to>::MIN as f64 && rounded <= <$to>::MAX as f64 {
                        Some(rounded as $to)
                    } else {
                        None
                    }
                }
            }
            impl NumericCast<$to> for f32 {
                fn cast(self) -> Option<$to> { NumericCast::<$to>::cast(f64::from(self)) }
            }
        )*
    };
}

int_to_int!(
    i8 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    i16 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    i32 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    i64 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    u8 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    u16 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    u32 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    u64 => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    isize => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize];
    usize => [i8, i16, i32, i64, u8, u16, u32, u64, isize, usize]
);
int_to_float!(i8, i16, i32, i64, u8, u16, u32, u64, isize, usize);
float_to_int!(i8, i16, i32, i64, u8, u16, u32, u64, isize, usize);

impl NumericCast<f64> for f64 {
    fn cast(self) -> Option<f64> {
        Some(self)
    }
}
impl NumericCast<f32> for f64 {
    fn cast(self) -> Option<f32> {
        Some(self as f32)
    }
}
impl NumericCast<f64> for f32 {
    fn cast(self) -> Option<f64> {
        Some(f64::from(self))
    }
}
impl NumericCast<f32> for f32 {
    fn cast(self) -> Option<f32> {
        Some(self)
    }
}

/// The row and the column of the boolean in the table of the managed original
/// (`TypeUtilities.Conversions` with `Convert.ChangeType`), for the integers
/// and the floating point numbers: true is one and false is zero, and a
/// number is true unless it is zero (not-a-number is true).
macro_rules! boolean_conversions {
    ($($ty:ty),*) => {
        $(
            ValueTypes::register_conversion::<bool, $ty>(|v| Some(u8::from(*v) as $ty));
            ValueTypes::register_conversion::<bool, Option<$ty>>(|v| Some(Some(u8::from(*v) as $ty)));
            ValueTypes::register_conversion::<$ty, bool>(|v| Some(*v != 0 as $ty));
            ValueTypes::register_conversion::<$ty, Option<bool>>(|v| Some(Some(*v != 0 as $ty)));
        )*
    };
}

/// The row and the column of the character in that table: a character and
/// an integer convert to each other when the code of the character is in the
/// range of the integer, and the integer in the range of the 16-bit
/// characters of the managed original (`Convert.ToChar` and its siblings
/// fail for the others). A character and a boolean, a floating point number
/// or a decimal do not convert.
macro_rules! character_conversions {
    ($($ty:ty),*) => {
        $(
            ValueTypes::register_conversion::<char, $ty>(|v| <$ty>::try_from(u32::from(*v)).ok());
            ValueTypes::register_conversion::<char, Option<$ty>>(|v| <$ty>::try_from(u32::from(*v)).ok().map(Some));
            ValueTypes::register_conversion::<$ty, char>(|v| u32::try_from(*v).ok().and_then(character_of_code));
            ValueTypes::register_conversion::<$ty, Option<char>>(|v| {
                u32::try_from(*v).ok().and_then(character_of_code).map(Some)
            });
        )*
    };
}

/// The character of a 16-bit code.
// Deviation (DEVIATIONS.md, Bindings): a code of the surrogate range, which the managed
// original holds as a character, is no character here.
fn character_of_code(code: u32) -> Option<char> {
    if code > 0xFFFF {
        return None;
    }
    char::from_u32(code)
}

macro_rules! primitive {
    ($($ty:ty),*) => {
        $(
            ValueTypes::register_display::<$ty>();
            ValueTypes::register_nullable::<$ty>();
            ValueTypes::register_parse::<$ty>(|s| s.trim().parse::<$ty>().ok());
            ValueTypes::register_conversion::<String, Option<$ty>>(|s| s.trim().parse::<$ty>().ok().map(Some));
        )*
    };
}

/// Whether the text form of a value of the type depends on the culture: the numbers and
/// the dates.
fn is_formatted_with_culture(id: TypeId) -> bool {
    macro_rules! any_of {
        ($($type_:ty),*) => { $(id == TypeId::of::<$type_>())||* };
    }
    any_of!(
        i8, i16, i32, i64, u8, u16, u32, u64, isize, usize, f32, f64,
        crate::utilities::Decimal, crate::utilities::DateTime, crate::utilities::DateTimeOffset
    )
}

/// How the text of a number of a type is read.
#[derive(Clone, Copy, PartialEq, Eq)]
enum NumberKind {
    /// `NumberStyles.Integer`: a sign and digits.
    Integer,
    /// `NumberStyles.Float | NumberStyles.AllowThousands` (the floating point types) and
    /// `NumberStyles.Number` (the decimal): a sign, group separators and a decimal separator.
    Fraction,
}

fn number_kind(id: TypeId) -> Option<NumberKind> {
    macro_rules! any_of {
        ($($type_:ty),*) => { $(id == TypeId::of::<$type_>())||* };
    }
    if any_of!(i8, i16, i32, i64, u8, u16, u32, u64, isize, usize) {
        Some(NumberKind::Integer)
    } else if any_of!(f32, f64, crate::utilities::Decimal) {
        Some(NumberKind::Fraction)
    } else {
        None
    }
}

/// The text of a number written with the symbols of `info`, rewritten with the symbols of
/// the invariant culture; `None` when the text holds an invariant symbol that means
/// something else in the culture (a `.` that is neither its decimal separator nor its group
/// separator), which the culture does not read as a number.
fn number_text_to_invariant(text: &str, kind: NumberKind, info: &crate::utilities::NumberFormatInfo) -> Option<String> {
    let mut text = text.trim().to_string();
    let decimal = info.number_decimal_separator();
    let group = info.number_group_separator();
    let negative = info.negative_sign();
    let positive = info.positive_sign();

    if kind == NumberKind::Fraction {
        if decimal != "." && group != "." && text.contains('.') {
            return None;
        }
        if !group.is_empty() && group != decimal {
            text = text.replace(group, "");
        }
        if decimal != "." && !decimal.is_empty() {
            text = text.replace(decimal, ".");
        }
    }
    if negative != "-" && !negative.is_empty() {
        if text.contains('-') {
            return None;
        }
        text = text.replace(negative, "-");
    }
    if positive != "+" && !positive.is_empty() {
        text = text.replace(positive, "+");
    }
    Some(text)
}

/// The name of the runtime library type a primitive mirrors.
fn primitive_full_name(id: TypeId) -> Option<&'static str> {
    macro_rules! names {
        ($($type_:ty => $name:literal),* $(,)?) => {
            $(if id == TypeId::of::<$type_>() { return Some($name); })*
        };
    }
    names!(
        bool => "System.Boolean", i8 => "System.SByte", u8 => "System.Byte", i16 => "System.Int16",
        u16 => "System.UInt16", i32 => "System.Int32", u32 => "System.UInt32", i64 => "System.Int64",
        u64 => "System.UInt64", isize => "System.IntPtr", usize => "System.UIntPtr", f32 => "System.Single",
        f64 => "System.Double", char => "System.Char", String => "System.String", &'static str => "System.String",
    );
    None
}

fn parse_bool(s: &str) -> Option<bool> {
    let s = s.trim();
    if s.eq_ignore_ascii_case("true") {
        Some(true)
    } else if s.eq_ignore_ascii_case("false") {
        Some(false)
    } else {
        None
    }
}

fn register_defaults() {
    primitive!(i8, i16, i32, i64, u8, u16, u32, u64, isize, usize, f32, f64, char);
    numeric_conversions!([i8, i16, i32, i64, u8, u16, u32, u64, isize, usize, f32, f64]);

    // The managed runtime shows booleans as "True"/"False".
    fn display_bool(value: &dyn AnyValue) -> String {
        match value.downcast_ref::<bool>() {
            Some(true) => "True".to_string(),
            _ => "False".to_string(),
        }
    }
    with_registry(|r| {
        r.display.insert(TypeId::of::<bool>(), display_bool);
    });
    ValueTypes::register_nullable::<bool>();
    ValueTypes::register_parse::<bool>(parse_bool);
    ValueTypes::register_conversion::<String, Option<bool>>(|s| parse_bool(s).map(Some));
    boolean_conversions!(i8, u8, i16, u16, i32, u32, i64, u64, f32, f64);
    {
        use crate::utilities::Decimal;

        ValueTypes::register_conversion::<bool, Decimal>(|v| Some(if *v { Decimal::ONE } else { Decimal::ZERO }));
        ValueTypes::register_conversion::<bool, Option<Decimal>>(|v| {
            Some(Some(if *v { Decimal::ONE } else { Decimal::ZERO }))
        });
        ValueTypes::register_conversion::<Decimal, bool>(|v| Some(!v.is_zero()));
        ValueTypes::register_conversion::<Decimal, Option<bool>>(|v| Some(Some(!v.is_zero())));
    }
    character_conversions!(i8, u8, i16, u16, i32, u32, i64, u64);

    ValueTypes::register_nullable::<String>();
    ValueTypes::register_conversion::<&'static str, String>(|s| Some((*s).to_string()));
    ValueTypes::register_conversion::<&'static str, Option<String>>(|s| Some(Some((*s).to_string())));

    ValueTypes::register_object::<FerroObject>();
    ValueTypes::register_object::<StyledElement>();
    ValueTypes::register_upcast::<StyledElement, FerroObject>();
    // Every class registers its handle type when it is initialised (see
    // `ObjectType::register_class`). The base classes that are used as
    // property types are also registered here, so that a null can be
    // converted to their nullable handle on a thread where the class was
    // not initialised yet. Conversions from a derived handle to a base
    // handle go through the root handle.
    ValueTypes::register_object::<crate::animation::Animatable>();
    ValueTypes::register_object::<crate::Visual>();
    ValueTypes::register_object::<crate::layout::Layoutable>();
    ValueTypes::register_object::<crate::interactivity::Interactive>();
    ValueTypes::register_object::<crate::input::InputElement>();
    ValueTypes::register_object::<crate::media::Brush>();
    ValueTypes::register_object::<crate::media::SolidColorBrush>();
    ValueTypes::register_object::<crate::media::GradientBrush>();
    ValueTypes::register_object::<crate::media::Transform>();
    ValueTypes::register_object::<crate::media::Geometry>();

    ValueTypes::register_display::<crate::metadata::MarkupDelegate>();
    ValueTypes::register_nullable::<crate::metadata::MarkupDelegate>();
    ValueTypes::register_nullable::<Rc<dyn crate::input::ICommand>>();
    ValueTypes::register_nullable::<crate::data::core::plugins::ObservableValue>();

    crate::utilities::Decimal::register_value_type();

    // The order of the values of the primitive types and of the dates (`IComparable`).
    macro_rules! orderings {
        ($($ty:ty),*) => {
            $( ValueTypes::register_ordering::<$ty>(); )*
        };
    }
    orderings!(
        i8, i16, i32, i64, u8, u16, u32, u64, isize, usize, bool, char, String,
        crate::utilities::Decimal, crate::utilities::DateTime, crate::utilities::DateTimeOffset, crate::animation::TimeSpan
    );
    ValueTypes::register_ordering_by::<f64>(|a, b| Some(float_order(*a, *b)));
    ValueTypes::register_ordering_by::<f32>(|a, b| Some(float_order(f64::from(*a), f64::from(*b))));
}

impl ValueTypes {
    /// Registers a conversion that needs the shared box itself (for reference
    /// types, whose box is the object).
    /// Registers an assignability cast that needs the shared box itself: the
    /// counterpart of [`register_cast`](Self::register_cast) for reference
    /// types, whose box is the object (for example the cast of a reference
    /// object to the handle of a contract it implements). A cast is also a
    /// conversion.
    pub fn register_boxed_cast<TFrom: 'static, TTo: PropertyValue>(cast: impl Fn(&BoxedValue) -> Option<TTo> + 'static) {
        let cast = ConvertFn::Boxed(Rc::new(move |v| cast(v).map(|v| Rc::new(v) as BoxedValue)));
        insert_cast((TypeId::of::<TFrom>(), TypeId::of::<TTo>()), cast);
    }

    pub fn register_boxed_conversion<TFrom: 'static, TTo: PropertyValue>(
        convert: impl Fn(&BoxedValue) -> Option<TTo> + 'static,
    ) {
        insert_conversion(
            (TypeId::of::<TFrom>(), TypeId::of::<TTo>()),
            ConvertFn::Boxed(Rc::new(move |v| convert(v).map(|v| Rc::new(v) as BoxedValue))),
        );
    }
}

